INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(101, 'Penggiat Kraf Perayaan', 'Penggiat kraf yang membuat hiasan perayaan pelbagai kaum dengan tangan sendiri (watak rekaan).', 'Memelihara kraf dan tradisi perayaan supaya semua kaum mengenali perayaan jiran mereka.', 'penggiat_kraf_perayaan_tradisional.png'),
(102, 'Ibu Kini', 'Ibu moden yang membawa anak-anaknya pulang beraya ke kampung dan bertanya tentang cara dahulu (watak rekaan).', 'Menghubungkan cara sambutan dahulu dengan cara kini untuk generasi muda.', 'ibu_kini.png'),
(103, 'Peniaga Rumah Kedai', 'Peniaga yang menjual kad, kuih dan hiasan untuk semua perayaan sepanjang tahun (watak rekaan).', 'Menyediakan keperluan perayaan semua kaum dan mengenali setiap pelanggannya.', 'peniaga_rumah_kedai.png'),
(104, 'Aishah', 'Gadis Muslim yang peramah dan petah bertanya (watak rekaan).', 'Mewakili perayaan Hari Raya Aidilfitri dan Aidiladha.', 'gadis_melayu.png'),
(105, 'Kavitha', 'Gadis India yang ceria dan suka melukis kolam (watak rekaan).', 'Mewakili perayaan Deepavali dan Thaipusam.', 'gadis_india.png'),
(106, 'Ah Meng', 'Pemuda Cina yang bertenaga dan suka bergurau (watak rekaan).', 'Mewakili perayaan Tahun Baharu Cina.', 'lengchai_cina.png'),
(107, 'Mei Ling', 'Gadis Buddha yang lembut tetapi bijak berjenaka (watak rekaan).', 'Mewakili sambutan Hari Wesak.', 'amoi_cina.png'),
(108, 'Daniel', 'Pemuda Sarawak yang mesra dan suka bergurau (watak rekaan).', 'Mewakili sambutan Krismas dan Hari Gawai.', 'orang_sarawak.png'),
(109, 'Linda', 'Gadis Kadazandusun yang bersemangat dan petah bercerita (watak rekaan).', 'Mewakili Pesta Kaamatan dan Unduk Ngadau.', 'gadis_sabah.png'),
(110, 'Harjit', 'Pemuda Sikh yang tenang dan ramah (watak rekaan).', 'Mewakili sambutan Vaisakhi.', 'jejaka_india.png'),
(111, 'Apai Jelani', 'Orang tua Iban yang mesra dan pandai bercerita (watak rekaan).', 'Mewakili Hari Gawai oleh petani kaum Dayak.', 'sarawakian.png'),
(112, 'Nenek Dahulu', 'Warga emas yang mengingati cara beraya pada zaman dahulu (watak rekaan).', 'Menceritakan cara sambutan perayaan dahulu kepada cucu-cucu.', 'nenek_dahulu.png'),
(113, 'Murid Sekolah', 'Murid yang gemar bertanya dan memegang telefon pintar (watak rekaan).', 'Mewakili generasi muda yang meraikan perayaan dengan cara kini.', 'budak_gajet.png'),
(114, 'Pak Nelayan', 'Nelayan peramah yang bersyukur dengan hasil laut (watak rekaan).', 'Mewakili sambutan San Pedro yang mensyukuri hasil laut.', 'nelayan.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(601, 'Bengkel Kraf Seribu Perayaan', 6, 'Masuki peranan penggiat kraf perayaan yang membuat hiasan untuk semua kaum. Dalam bengkelmu kau mengenali perayaan utama, tarikh dan maknanya.'),
(602, 'Pulang Beraya Bersama Nenek', 6, 'Masuki peranan seorang ibu moden yang membawa anak pulang beraya ke kampung. Bersama Nenek Dahulu, kau mengenali tujuan perayaan, cara sambutan dahulu dan kini, serta amalan yang kekal.'),
(603, 'Kedai Seribu Perayaan', 6, 'Masuki peranan peniaga rumah kedai yang menjual kad, kuih dan hiasan untuk semua perayaan. Setiap pelanggan membawa cerita tentang perayaan, Rumah Terbuka Malaysia dan nilai menghormati.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e6_n1_s1', 'Bengkel kraf di tengah bandar. Enam tempahan hiasan sampai serentak, iaitu tarikh perayaan tertulis pada kertas yang basah terkena hujan dan separuh luntur.', 1, 601, 'bandar.png'),
('e6_n1_s2', 'Bengkel dipenuhi kad Selamat Hari Raya. Dua pelanggan Muslim mahu menempah hiasan, tetapi seorang bertanya mengapa ada dua hari raya dengan makna berbeza.', 2, 601, 'suasana_dan_ucapan_raya_kini.png'),
('e6_n1_s3', 'Rumah keluarga Cina menjelang Tahun Baharu Cina. Seluruh ahli keluarga berkumpul. Ah Meng mahu mengatur senarai kegiatan perayaan, tetapi kad tertukar tempat.', 3, 601, 'makan_besar_cina_dahulu.png'),
('e6_n1_s4', 'Pelataran rumah menjelang Deepavali. Kavitha dan Harjit membincangkan perayaan masing-masing. Deepavali, Thaipusam dan Vaisakhi. Kad hiasan bercampur di atas tikar.', 4, 601, 'kolam_deepavali_dahulu.png'),
('e6_n1_s5', 'Rumah panjang di Sarawak menjelang 1 Jun. Apai Jelani dan Linda berbalah tentang perayaan petani di Sarawak dan Sabah. Dua kad bercampur.', 5, 601, 'hari_gawai_dayak_dahulu.png'),
('e6_n1_s6', 'Taman perayaan. Daniel dan Mei Ling berbual tentang Krismas dan Wesak. Murid yang lalu bertanya mengapa tarikh dan kegiatan kedua-dua perayaan sangat berbeza.', 6, 601, 'tempat_beribadat_berdekat.png'),
('e6_n1_s7', 'Perkampungan Orang Asli di Selangor. Tok Batin Temiar dan Pak Mah Meri mengira hari menjelang 31 Disember. Mereka berbalah tentang nama sambutan tahun baharu setiap suku.', 7, 601, 'petempatan_semua_kini.png'),
('e6_n1_s8', 'Pelabuhan kecil di Melaka pada bulan Jun. Pak Nelayan menghias kapal dengan bendera dan bunga. Seorang pelancong bertanya perayaan apa ini dan mengapa kapal dihias.', 8, 601, 'bandar.png'),
('e6_n2_s1', 'Halaman rumah nenek sehari sebelum raya. Anak-anak bertanya mengapa begitu banyak perayaan di Malaysia dan apa tujuannya. Nenek mengeluarkan sekeping kad tujuan perayaan.', 1, 602, 'petempatan_semua_kini.png'),
('e6_n2_s2', 'Ruang tamu nenek. Sebuah kotak lama berisi kad ucapan raya dari pos. Cucu menunjukkan telefon yang penuh ucapan digital.', 2, 602, 'suasana raya_dan_kad_ucapan_dahulu.png'),
('e6_n2_s3', 'Sebuah gambar lama kedai gambar di bandar. Nenek menunjukkan foto keluarga bergaya dengan latar lukisan. Cucu cuba mencari bukti di dalam gambar bahawa kisah nenek benar.', 3, 602, 'mengambil_foto_dahulu.png'),
('e6_n2_s4', 'Rumah Kavitha menjelang Deepavali. Keluarga duduk bersama membuat kolam. Cucu bertanya mengapa kolam kini berwarna-warni sedangkan dahulu hanya putih.', 4, 602, 'kolam_deepavali_sekarang.png'),
('e6_n2_s5', 'Restoran mewah pada malam Tahun Baharu Cina. Ah Meng bertanya mengapa keluarganya makan besar di restoran, sedangkan datuknya dahulu makan di rumah.', 5, 602, 'makan_besar_cina_sekarang.png'),
('e6_n2_s6', 'Dapur nenek. Beberapa jiran bergotong-royong menyediakan kuih. Cucu hairan mengapa kuih dahulu disediakan lama sedangkan kini boleh dibeli di kedai.', 6, 602, 'penyediaan_kuih_muih_tradisional.png'),
('e6_n2_s7', 'Kedai kuih di bandar. Rak penuh balang kuih raya dan hamper. Cucu membeli kuih dan bertanya kepada nenek sama ada beli kuih bermakna tradisi hilang.', 7, 602, 'pembelian_kuih_muih_kini.png'),
('e6_n2_s8', 'Pesta Kaamatan di tepi sawah. Linda dan nenek menonton pertandingan Unduk Ngadau. Murid bertanya bagaimana pemenang dipilih dahulu berbanding kini.', 8, 602, 'unduk_ngadau_dahulu.png'),
('e6_n2_s9', 'Petang hari raya. Keluarga besar pulang ke kampung dan bersalam-salaman. Cucu menerima duit raya dan nenek bertanya apa lagi yang masih kekal dari dahulu.', 9, 602, 'suasana_dan_ucapan_raya_kini.png'),
('e6_n3_s1', 'Sebuah rumah kedai pada hari terakhir sebelum cuti perayaan. Kerajaan menetapkan enam perayaan utama sebagai Rumah Terbuka Malaysia. Pelanggan bertanya perayaan mana yang termasuk.', 1, 603, 'bandar.png'),
('e6_n3_s2', 'Rak kad ucapan Selamat Hari Raya. Seorang pelanggan Muslim membeli kad untuk jiran Cina dan India. Dia bertanya mengapa perlu meraikan perayaan bersama keluarga.', 2, 603, 'petempatan_semua_kini.png'),
('e6_n3_s3', 'Hari raya kedua. Pelanggan Cina melawat jiran Melayu dan membawa makanan. Seorang kanak-kanak bertanya tentang adab melawat rumah perayaan kaum lain.', 3, 603, 'petempatan_semua_kini.png'),
('e6_n3_s4', 'Rumah panjang masa kini pada 1 Jun. Pelbagai kaum menyertai Gawai, termasuk tetamu Melayu dan Cina. Seorang tetua kehairanan mengapa ramai kaum lain turut menyambut.', 4, 603, 'festival_gawai_kini.png'),
('e6_n3_s5', 'Ruang pameran di tingkat atas kedai. Gambar kolam, makan besar dan kuih dari dahulu dan kini terpampang. Pelanggan diminta memadankan perubahan tradisi.', 5, 603, 'kolam_deepavali_dahulu.png'),
('e6_n3_s6', 'Papan putih di bahagian belakang kedai. Pekerja kedai membincangkan analisis SWOT untuk mengekalkan warisan perayaan. Sekeping kad SWOT tergantung senget.', 6, 603, 'petempatan_semua_dahulu.png'),
('e6_n3_s7', 'Hari terakhir sebelum kedai ditutup. Pelanggan terakhir meminta ringkasan perayaan, iaitu tujuan, cara sambutan dan amalan kekal. Kad berselerak di atas kaunter.', 7, 603, 'bandar.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(601, 'e6_n1_s1', 'Kertas Tempahan Basah', 'Padankan perayaan dengan tarikh sambutannya.', '4', 'Mengenal pasti tarikh perayaan: Aidilfitri (1 Syawal), Aidiladha (10 Zulhijah), Tahun Baharu Cina (hari pertama kalendar Cina), Krismas (25 Disember), Hari Gawai (1 Jun), Pesta Kaamatan (Mei).', '{"pairs": [{"text": "Hari Raya Aidilfitri", "pair": 1}, {"text": "1 Syawal mengikut kalendar Islam", "pair": 1}, {"text": "Hari Raya Aidiladha", "pair": 2}, {"text": "10 Zulhijah mengikut kalendar Islam", "pair": 2}, {"text": "Tahun Baharu Cina", "pair": 3}, {"text": "Hari pertama dalam kalendar Cina", "pair": 3}, {"text": "Krismas", "pair": 4}, {"text": "25 Disember setiap tahun", "pair": 4}, {"text": "Hari Gawai", "pair": 5}, {"text": "1 Jun setiap tahun", "pair": 5}, {"text": "Pesta Kaamatan", "pair": 6}, {"text": "Bulan Mei setiap tahun", "pair": 6}], "aftermath": "Tarikh tersilap dan hiasan tiba pada hari yang salah. Pelanggan kecewa kerana perayaan mereka tidak dihormati.", "turns": [{"after": 8, "options": [{"text": "Setiap perayaan ada tarikh dan makna tersendiri, jadi kita perlu menghormatinya.", "isCorrect": true, "reaction": "Betul. Hiasan kami dihantar tepat pada masanya."}, {"text": "Semua perayaan sama sahaja, jadi tarikh tidak penting.", "isCorrect": false, "reaction": "Pelanggan memprotes kerana perayaan mereka dianggap remeh."}, {"text": "Hiasan boleh dihantar bila-bila masa sahaja.", "isCorrect": false, "reaction": "Perayaan berlalu tanpa hiasan dan pelanggan kecewa."}], "clue": "Hormati tarikh setiap perayaan."}]}'),
(602, 'e6_n1_s2', 'Kad Dua Hari Raya', 'Baca kad dan tentukan perayaan yang melibatkan ibadah korban.', '5', 'Membezakan Aidilfitri (1 Syawal, selepas puasa sebulan) dengan Aidiladha (10 Zulhijah, hari Tasyrik 11, 12 dan 13, ibadah korban dan sedekah daging).', '{"clueText": "Kad: Perayaan ini disambut oleh masyarakat Islam pada 10 Zulhijah dan diteruskan pada hari Tasyrik, iaitu 11, 12 dan 13 Zulhijah. Umat Islam mengadakan ibadah korban dan memberikan sedekah daging korban tersebut.", "options": [{"text": "Hari Raya Aidiladha.", "isCorrect": true}, {"text": "Hari Raya Aidilfitri.", "isCorrect": false, "consequence": "Aidilfitri disambut pada 1 Syawal selepas puasa sebulan. Kad dikembalikan."}, {"text": "Pesta Kaamatan.", "isCorrect": false, "consequence": "Kaamatan perayaan kaum Kadazandusun dan Murut. Aishah tersenyum kecil."}, {"text": "Deepavali.", "isCorrect": false, "consequence": "Deepavali perayaan masyarakat Hindu. Kad dikembalikan."}], "aftermath": "Kad tersalah baca dan hiasan Aidilfitri dihantar untuk Aidiladha. Aishah menggeleng.", "turns": [{"after": 6, "options": [{"text": "Kedua-dua hari raya mempunyai makna dan tarikh berbeza, jadi hiasan juga berbeza.", "isCorrect": true, "reaction": "Betul. Hiasan Aidiladha disesuaikan dengan maknanya."}, {"text": "Kedua-dua hari raya sama sahaja, satu hiasan memadai.", "isCorrect": false, "reaction": "Aishah kecewa kerana makna perayaannya diabaikan."}, {"text": "Aidiladha tidak penting untuk dihias.", "isCorrect": false, "reaction": "Pelanggan menegur kerana perayaan itu juga disambut dengan meriah."}], "clue": "Dua hari raya, dua makna."}]}'),
(603, 'e6_n1_s3', 'Urutan Tahun Baharu Cina', 'Susun kegiatan Tahun Baharu Cina mengikut urutan.', '1', 'Memahami Tahun Baharu Cina: makan malam keluarga, hari pertama kalendar Cina, berlanjutan 15 hari hingga Chap Goh Meh.', '{"timelineItems": [{"id": 1, "year": "Malam sebelum itu", "text": "Seluruh ahli keluarga berkumpul untuk makan malam bersama-sama", "why": "Perayaan bermula dengan makan malam keluarga."}, {"id": 2, "year": "Hari pertama", "text": "Tahun Baharu Cina disambut pada hari pertama dalam kalendar Cina", "why": "Itulah hari sambutan utama."}, {"id": 3, "year": "Selama 15 hari", "text": "Perayaan berlanjutan dengan sambutan di rumah dan tempat awam", "why": "Perayaan tidak berakhir pada hari pertama sahaja."}, {"id": 4, "year": "Hari ke-15", "text": "Perayaan berakhir pada hari Chap Goh Meh", "why": "Hari terakhir sambutan."}], "aftermath": "Urutan tersilap dan keluarga terlepas hari penting. Ah Meng menggaru kepala.", "turns": [{"after": 5, "options": [{"text": "Perayaan itu meraikan tahun baharu dan menyatukan keluarga.", "isCorrect": true, "reaction": "Betul. Keluarga kami berasa bangga."}, {"text": "Perayaan itu hanya untuk makan besar sahaja.", "isCorrect": false, "reaction": "Ah Meng berasa maksud perayaan dikecilkan."}, {"text": "Perayaan itu hanya berlangsung satu hari.", "isCorrect": false, "reaction": "Nenek membetulkan kerana ia berlanjutan selama 15 hari."}], "clue": "Meraikan tahun baharu dan menyatukan keluarga."}]}'),
(604, 'e6_n1_s4', 'Tiga Perayaan India dan Sikh', 'Padankan perayaan dengan ciri atau makna sambutannya.', '4', 'Memahami Deepavali (Aippasi, kecerahan mengatasi kegelapan, kolam dan pelita), Thaipusam (Dewa Murugan, pembayar niat), Vaisakhi (bulan Vaisakh, Gurdwara, syukur tanaman).', '{"pairs": [{"text": "Deepavali", "pair": 1}, {"text": "Kecerahan mengatasi kegelapan, kolam dan pelita", "pair": 1}, {"text": "Thaipusam", "pair": 2}, {"text": "Pembayar niat membawa persembahan kepada Dewa Murugan", "pair": 2}, {"text": "Vaisakhi", "pair": 3}, {"text": "Kaum Sikh bersembahyang di Gurdwara dan mensyukuri hasil tanaman", "pair": 3}], "aftermath": "Kad bertukar dan hiasan Deepavali digantung di Gurdwara. Harjit dan Kavitha kecewa.", "turns": [{"after": 6, "options": [{"text": "Setiap perayaan ada makna sendiri, jadi hiasan mesti sesuai.", "isCorrect": true, "reaction": "Betul, kami berasa dihargai."}, {"text": "Semua hiasan boleh digantung di mana-mana sahaja.", "isCorrect": false, "reaction": "Pelanggan terasa dipandang remeh."}, {"text": "Hiasan perayaan tidak perlu mengikut makna.", "isCorrect": false, "reaction": "Tempahan dikembalikan kerana hiasan tidak sesuai."}], "clue": "Hiasan mesti sesuai dengan makna."}]}'),
(605, 'e6_n1_s5', 'Gawai dan Kaamatan', 'Padankan perayaan petani dengan kaum dan cirinya.', '4', 'Membezakan Hari Gawai (Dayak, Iban dan Bidayuh, 1 Jun, ngajat) dengan Pesta Kaamatan (Kadazandusun dan Murut, Mei, Magavau, sumazau, Unduk Ngadau).', '{"pairs": [{"text": "Hari Gawai", "pair": 1}, {"text": "Kaum Dayak, Iban dan Bidayuh, 1 Jun, ngajat di rumah panjang", "pair": 1}, {"text": "Pesta Kaamatan", "pair": 2}, {"text": "Kadazandusun dan Murut, bulan Mei, Magavau oleh Bobohizan", "pair": 2}, {"text": "Tarian sumazau", "pair": 3}, {"text": "Diadakan semasa Pesta Kaamatan", "pair": 3}, {"text": "Unduk Ngadau", "pair": 4}, {"text": "Pertandingan semasa Pesta Kaamatan", "pair": 4}], "aftermath": "Kad bertukar dan Gawai dikatakan perayaan Sabah. Apai Jelani dan Linda berasa perayaan mereka disalah faham.", "turns": [{"after": 6, "options": [{"text": "Kedua-duanya kesyukuran hasil tani, tetapi tarikh dan kaum yang menyambutnya berbeza.", "isCorrect": true, "reaction": "Betul, kami faham sekarang."}, {"text": "Kedua-duanya sama dan disambut kaum yang sama.", "isCorrect": false, "reaction": "Apai Jelani dan Linda membantah serentak."}, {"text": "Kedua-duanya tidak mempunyai tujuan.", "isCorrect": false, "reaction": "Mereka menggeleng kerana kedua-duanya kesyukuran atas hasil tani."}], "clue": "Kesyukuran hasil tani, tarikh berlainan."}]}'),
(606, 'e6_n1_s6', 'Krismas dan Wesak', 'Padankan perayaan dengan ciri atau makna sambutannya.', '4', 'Memahami Krismas (25 Disember, kelahiran Jesus Christ, hadiah dan karol) dan Wesak (Mei, tiga peristiwa Siddharta, memandikan patung Buddha, makanan kepada sami).', '{"pairs": [{"text": "Krismas", "pair": 1}, {"text": "Memperingati kelahiran Jesus Christ, hadiah dan karol", "pair": 1}, {"text": "Hari Wesak", "pair": 2}, {"text": "Tiga peristiwa penting hidup Siddharta Gautama", "pair": 2}, {"text": "Memandikan patung Buddha", "pair": 3}, {"text": "Penyucian diri semasa Wesak", "pair": 3}, {"text": "Karol", "pair": 4}, {"text": "Nyanyian gembira dari rumah ke rumah semasa Krismas", "pair": 4}], "aftermath": "Kad bertukar dan karol dikatakan nyanyian Wesak. Daniel dan Mei Ling terasa dilucutkan makna perayaan mereka.", "turns": [{"after": 7, "options": [{"text": "Mandi patung bermakna penyucian diri semasa Wesak.", "isCorrect": true, "reaction": "Betul. Murid itu mengangguk faham."}, {"text": "Mandi patung bermakna bermain air.", "isCorrect": false, "reaction": "Mei Ling menggeleng kerana maknanya lebih mendalam."}, {"text": "Mandi patung bermakna menyambut tahun baharu.", "isCorrect": false, "reaction": "Itu tidak betul. Wesak mengingati peristiwa penting dalam hidup Siddharta."}], "clue": "Mandi patung: penyucian diri."}]}'),
(607, 'e6_n1_s7', 'Tahun Baharu Orang Asli', 'Padankan suku Orang Asli dengan nama sambutan tahun baharu atau perayaannya.', '4', 'Mengenal pasti sambutan Orang Asli: Jakun (Tahon Baro), Semai (Jis Pai), Temuan (Tahun Bahauk), Mah Meri (Tawun Empai), Genggulang (Semai), Hari Moyang (Selangor dan Negeri Sembilan).', '{"pairs": [{"text": "Suku Jakun", "pair": 1}, {"text": "Tahon Baro", "pair": 1}, {"text": "Suku Semai", "pair": 2}, {"text": "Jis Pai", "pair": 2}, {"text": "Suku Temuan", "pair": 3}, {"text": "Tahun Bahauk", "pair": 3}, {"text": "Suku Mah Meri", "pair": 4}, {"text": "Tawun Empai", "pair": 4}, {"text": "Suku Semai berdoa kesejahteraan", "pair": 5}, {"text": "Hari Genggulang", "pair": 5}, {"text": "Orang Asli Selangor dan Negeri Sembilan", "pair": 6}, {"text": "Hari Moyang", "pair": 6}], "aftermath": "Nama sambutan tersilap dan Orang Asli terasa perayaan mereka tidak dikenali. Tok Batin menunduk.", "turns": [{"after": 7, "options": [{"text": "Setiap suku mempunyai nama sambutan sendiri, jadi kita menghormati perbezaan itu.", "isCorrect": true, "reaction": "Betul, nak. Kami berasa dihargai."}, {"text": "Semua suku menyebut nama yang sama.", "isCorrect": false, "reaction": "Pak Mah Meri tersenyum pahit kerana namanya tidak diketahui."}, {"text": "Orang Asli tidak mempunyai sambutan tahun baharu.", "isCorrect": false, "reaction": "Tok Batin terguris. Sambutan itu bermula pada 31 Disember."}], "clue": "Setiap suku ada nama sambutan sendiri."}]}'),
(608, 'e6_n1_s8', 'Papan Perayaan Pelabuhan', 'Baca papan dan tentukan perayaan masyarakat berketurunan Portugis di Melaka.', '5', 'Memahami San Pedro: disambut masyarakat berketurunan Portugis di Melaka pada bulan Jun, meraikan penaung nelayan, kapal dihias, tarian branyo.', '{"clueText": "Papan: Perayaan ini disambut oleh masyarakat berketurunan Portugis di Melaka pada bulan Jun. Perayaan ini meraikan penaung nelayan. Kapal-kapal dihias indah oleh nelayan dan tarian branyo yang diwarisi sejak dahulu ditarikan.", "options": [{"text": "San Pedro.", "isCorrect": true}, {"text": "Hari Gawai.", "isCorrect": false, "consequence": "Gawai disambut pada 1 Jun di Sarawak. Papan menyebut Melaka."}, {"text": "Thaipusam.", "isCorrect": false, "consequence": "Thaipusam disambut oleh masyarakat Hindu. Papan dikembalikan."}, {"text": "Wesak.", "isCorrect": false, "consequence": "Wesak disambut oleh penganut Buddha. Pelancong keliru."}], "aftermath": "Papan tersalah baca dan pelancong pulang dengan cerita salah tentang San Pedro.", "turns": [{"after": 6, "options": [{"text": "San Pedro ialah perayaan masyarakat berketurunan Portugis dan patut dihormati.", "isCorrect": true, "reaction": "Betul. Pelancong turut bertepuk."}, {"text": "San Pedro hanya perayaan pelancong.", "isCorrect": false, "reaction": "Pak Nelayan terkilan kerana perayaan itu warisan mereka."}, {"text": "San Pedro tidak mempunyai tujuan.", "isCorrect": false, "reaction": "Pak Nelayan membetulkan. Tujuannya meraikan penaung nelayan."}], "clue": "San Pedro: warisan masyarakat Portugis."}]}'),
(609, 'e6_n2_s1', 'Lima Tujuan Perayaan', 'Padankan tujuan perayaan dengan perayaannya.', '4', 'Memahami tujuan perayaan: keagamaan, meraikan tahun baharu, mensyukuri hasil tanaman atau hasil laut, unsur baik mengatasi kejahatan, mengingati tokoh agama.', '{"pairs": [{"text": "Keagamaan", "pair": 1}, {"text": "Aidilfitri, Aidiladha, Krismas dan Thaipusam", "pair": 1}, {"text": "Meraikan tahun baharu", "pair": 2}, {"text": "Tahun Baharu Cina, Tahon Baro, Jis Pai dan Tawun Empai", "pair": 2}, {"text": "Mensyukuri hasil tanaman atau hasil laut", "pair": 3}, {"text": "Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro", "pair": 3}, {"text": "Mengharapkan unsur baik mengatasi kejahatan", "pair": 4}, {"text": "Deepavali", "pair": 4}, {"text": "Mengingati tokoh agama", "pair": 5}, {"text": "Hari Wesak", "pair": 5}], "aftermath": "Tujuan tersilap dan anak-anak menyangka semua perayaan sama sahaja. Nenek menggeleng.", "turns": [{"after": 7, "options": [{"text": "Setiap perayaan ada tujuan tersendiri, jadi kita menghormati cara sambutan berbeza.", "isCorrect": true, "reaction": "Betul. Nenek tersenyum."}, {"text": "Semua perayaan sama sahaja tujuannya.", "isCorrect": false, "reaction": "Anak-anak keliru kerana ada banyak tujuan berbeza."}, {"text": "Perayaan hanya untuk bergembira.", "isCorrect": false, "reaction": "Nenek menggeleng kerana ada tujuan agama dan kesyukuran."}], "clue": "Setiap perayaan ada tujuan sendiri."}]}'),
(610, 'e6_n2_s2', 'Dari Kad ke Skrin', 'Padankan cara menyampaikan ucapan dahulu dan kini.', '4', 'Membezakan cara sambutan dahulu dan kini: kad ucapan melalui pos atau serahan tangan, kini melalui media elektronik dan media sosial; foto di kedai gambar, kini swafoto.', '{"pairs": [{"text": "Ucapan dahulu", "pair": 1}, {"text": "Kad dihantar melalui pos atau serahan tangan", "pair": 1}, {"text": "Ucapan kini", "pair": 2}, {"text": "Dihantar melalui media elektronik dan media sosial", "pair": 2}, {"text": "Foto dahulu", "pair": 3}, {"text": "Foto keluarga diambil di kedai gambar", "pair": 3}, {"text": "Foto kini", "pair": 4}, {"text": "Swafoto bersama keluarga dimuat naik di media sosial", "pair": 4}], "aftermath": "Cara tersilap dan cucu menyangka nenek tidak pernah menghantar ucapan. Nenek terguris.", "turns": [{"after": 7, "options": [{"text": "Cara sambutan berubah, tetapi tujuan mengucap selamat tetap sama.", "isCorrect": true, "reaction": "Betul. Nenek senyum lebar."}, {"text": "Ucapan dahulu tidak bermakna kerana lambat.", "isCorrect": false, "reaction": "Nenek terguris. Setiap kad membawa makna."}, {"text": "Ucapan kini tidak bermakna kerana digital.", "isCorrect": false, "reaction": "Cucu terasa dirinya dipandang remeh."}], "clue": "Cara berubah, makna kekal."}]}'),
(611, 'e6_n2_s3', 'Cari Bukti Kedai Gambar', 'Cari empat bukti cara bergambar semasa perayaan dahulu.', '2', 'Mengenal pasti cara dahulu mengambil foto keluarga di kedai gambar berbanding swafoto kini.', '{"bgImage": "../assets/gameAsset/background/mengambil_foto_dahulu.png", "hotspots": [{"name": "Kamera lama: foto keluarga diambil di kedai gambar", "top": "49.5%", "left": "14.9%"}, {"name": "Latar lukisan studio kedai gambar untuk foto keluarga dahulu", "top": "40%", "left": "55%"}, {"name": "Kerusi untuk bergambar bersama keluarga di kedai gambar", "top": "70%", "left": "52%"}, {"name": "Lampu studio kedai gambar pada zaman dahulu", "top": "20.7%", "left": "97.7%"}], "aftermath": "Bukti tidak ditemui dan cucu menyangka kisah nenek hanya dongeng.", "turns": [{"after": 6, "options": [{"text": "Gambar dahulu ialah bukti sejarah keluarga yang perlu dijaga.", "isCorrect": true, "reaction": "Betul, cucu. Nenek akan tunjuk album."}, {"text": "Gambar lama tidak perlu disimpan.", "isCorrect": false, "reaction": "Nenek terdiam. Album itu kenangan keluarga."}, {"text": "Gambar lama tidak penting kerana kabur.", "isCorrect": false, "reaction": "Nenek terguris kerana gambar itu satu-satunya bukti kenangan lama."}], "clue": "Simpan gambar sebagai bukti sejarah."}]}'),
(612, 'e6_n2_s4', 'Cari Bukti Kolam Kini', 'Cari empat bukti kolam Deepavali masa kini.', '2', 'Membezakan kolam dahulu (tepung) dengan kini (beras atau hampas kelapa berwarna-warni).', '{"bgImage": "../assets/gameAsset/background/kolam_deepavali_sekarang.png", "hotspots": [{"name": "Kolam kini daripada beras atau hampas kelapa berwarna-warni", "top": "48.2%", "left": "34.8%"}, {"name": "Kanak-kanak melukis kolam beramai-ramai", "top": "60.6%", "left": "81.9%"}, {"name": "Keluarga duduk bersama membuat kolam pada Deepavali", "top": "42.2%", "left": "10.7%"}, {"name": "Pelita di tengah kolam semasa Deepavali", "top": "65.3%", "left": "36.8%"}], "aftermath": "Bukti tidak ditemui dan cucu menyangka kolam sentiasa dibuat dengan cara yang sama.", "turns": [{"after": 7, "options": [{"text": "Bahan berubah tetapi tradisi menghias rumah dengan kolam masih diteruskan.", "isCorrect": true, "reaction": "Betul. Itulah kesinambungannya."}, {"text": "Tradisi kolam sudah hilang.", "isCorrect": false, "reaction": "Kavitha menggeleng kerana kolam masih dibuat."}, {"text": "Kolam hanya hiasan tanpa makna.", "isCorrect": false, "reaction": "Kavitha terguris. Ia sebahagian tradisi Deepavali."}], "clue": "Bahan berubah, tradisi kekal."}]}'),
(613, 'e6_n2_s5', 'Nota Makan Besar', 'Baca nota dan tentukan perubahan tradisi makan besar Tahun Baharu Cina.', '5', 'Memahami perubahan: tradisi makan besar masih diraikan, tetapi sesetengah keluarga memilih makan di restoran atau hotel.', '{"clueText": "Nota: Tradisi makan besar di rumah dengan berkumpul bersama-sama keluarga pada malam Tahun Baharu Cina masih diraikan. Walau bagaimanapun, terdapat keluarga yang memilih untuk menikmatinya di tempat lain.", "options": [{"text": "Tradisi masih diraikan tetapi ada keluarga memilih restoran atau hotel.", "isCorrect": true}, {"text": "Tradisi sudah dihentikan sepenuhnya.", "isCorrect": false, "consequence": "Nota menyatakan tradisi masih diraikan. Ah Meng membetulkan."}, {"text": "Semua keluarga memilih makan di rumah sahaja.", "isCorrect": false, "consequence": "Nota menyebut sebahagian memilih tempat lain."}, {"text": "Makan besar bertukar menjadi pertandingan memasak.", "isCorrect": false, "consequence": "Tiada maklumat itu dalam nota."}], "aftermath": "Nota tersalah baca dan keluarga Ah Meng bertengkar tentang tempat makan besar.", "turns": [{"after": 5, "options": [{"text": "Tempat boleh berubah, tetapi berkumpul bersama keluarga tetap penting.", "isCorrect": true, "reaction": "Betul, nek. Datuk tersenyum."}, {"text": "Berkumpul bersama keluarga tidak penting lagi.", "isCorrect": false, "reaction": "Ah Meng terkilan. Nilai itulah inti tradisi."}, {"text": "Restoran mengubah makna perayaan sepenuhnya.", "isCorrect": false, "reaction": "Nenek menggeleng kerana makna perayaan masih sama."}], "clue": "Berkumpul bersama keluarga tetap penting."}]}'),
(614, 'e6_n2_s6', 'Kad Penyediaan Kuih', 'Baca kad dan tentukan cara menyediakan kuih dahulu.', '5', 'Memahami cara penyediaan kuih dahulu: bahan dan kaedah tradisional serta dilakukan secara gotong-royong.', '{"clueText": "Kad: Penyediaan kuih-muih dahulu menggunakan bahan dan kaedah tradisional. Kerja itu dilakukan secara gotong-royong oleh jiran dan keluarga.", "options": [{"text": "Menggunakan bahan dan kaedah tradisional secara gotong-royong.", "isCorrect": true}, {"text": "Menggunakan mesin moden dengan seorang pekerja.", "isCorrect": false, "consequence": "Kad menyebut kaedah tradisional dan gotong-royong."}, {"text": "Membeli kuih siap di kedai.", "isCorrect": false, "consequence": "Itu cara kini. Kad menerangkan cara dahulu."}, {"text": "Mengimport kuih dari luar negara.", "isCorrect": false, "consequence": "Tiada dalam kad. Nenek ketawa kecil."}], "aftermath": "Kad tersalah baca dan cucu menyangka nenek tidak pernah bekerjasama dengan jiran. Nenek terguris.", "turns": [{"after": 5, "options": [{"text": "Gotong-royong mengeratkan hubungan jiran dan keluarga.", "isCorrect": true, "reaction": "Betul. Nenek tersenyum bangga."}, {"text": "Gotong-royong menyusahkan dan tidak perlu.", "isCorrect": false, "reaction": "Jiran yang membantu terdiam."}, {"text": "Gotong-royong hanya untuk orang tua.", "isCorrect": false, "reaction": "Cucu ditegur kerana semua boleh membantu."}], "clue": "Gotong-royong mengeratkan hubungan."}]}'),
(615, 'e6_n2_s7', 'Cari Bukti Kuih Kini', 'Cari empat bukti kuih raya mudah dibeli pada masa kini.', '2', 'Memahami kelebihan peralatan moden: memudahkan penyediaan kuih, kuih raya mudah dibeli, mempercepatkan proses penghasilan.', '{"bgImage": "../assets/gameAsset/background/pembelian_kuih_muih_kini.png", "hotspots": [{"name": "Rak balang kuih raya: kuih raya mudah dibeli di kedai", "top": "44%", "left": "43.4%"}, {"name": "Juruwang kedai: kuih kini dibeli dengan mudah", "top": "52.7%", "left": "65.9%"}, {"name": "Beg hadiah dan hamper kuih raya yang siap dibungkus", "top": "83%", "left": "8.4%"}, {"name": "Papan Selamat Hari Raya", "top": "33.4%", "left": "71.9%"}], "aftermath": "Bukti tidak ditemui dan cucu menyangka beli kuih bermakna tradisi mati.", "turns": [{"after": 6, "options": [{"text": "Beli atau buat sendiri, semangat berkongsi kuih masih kekal.", "isCorrect": true, "reaction": "Itu betul, cucu."}, {"text": "Beli kuih bermakna tiada tradisi lagi.", "isCorrect": false, "reaction": "Nenek menggeleng kerana amalan berkongsi masih ada."}, {"text": "Kuih beli tidak boleh dijadikan hidangan raya.", "isCorrect": false, "reaction": "Nenek ketawa kerana kuih beli juga dihidang."}], "clue": "Semangat berkongsi kekal."}]}'),
(616, 'e6_n2_s8', 'Cari Bukti Unduk Ngadau', 'Cari empat bukti Pesta Kaamatan dahulu.', '2', 'Memahami Unduk Ngadau: dahulu pemenang dipilih berdasarkan semangat Huminodun (berkorban menyelamatkan generasinya); kini melalui sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.', '{"bgImage": "../assets/gameAsset/background/unduk_ngadau_dahulu.png", "hotspots": [{"name": "Pemenang Unduk Ngadau dahulu: dipilih berdasarkan semangat Huminodun", "top": "32.1%", "left": "69.2%"}, {"name": "Tiga peserta Unduk Ngadau menunggu keputusan di tepi pentas", "top": "51.2%", "left": "40.3%"}, {"name": "Pentas pondok Pesta Kaamatan di tepi sawah", "top": "57.6%", "left": "63.2%"}, {"name": "Sawah padi: hasil tanaman yang disyukuri semasa Kaamatan dan Gawai", "top": "59.5%", "left": "8.1%"}], "aftermath": "Bukti tidak ditemui dan semangat Huminodun dilupakan. Linda kecewa.", "turns": [{"after": 5, "options": [{"text": "Pemilihan berubah, tetapi nilai berkorban dan menghargai sejarah masih penting.", "isCorrect": true, "reaction": "Betul, nak."}, {"text": "Semangat Huminodun tidak penting lagi.", "isCorrect": false, "reaction": "Linda terkilan kerana nilai itu warisan kaumnya."}, {"text": "Unduk Ngadau hanya pertandingan rupa.", "isCorrect": false, "reaction": "Linda membetulkan. Ia berkaitan semangat Huminodun."}], "clue": "Nilai berkorban kekal penting."}]}'),
(617, 'e6_n2_s9', 'Kad Amalan Kekal', 'Baca kad dan tentukan amalan yang terus kekal dalam sambutan perayaan.', '5', 'Memahami amalan yang kekal: tradisi balik ke kampung, pemberian duit raya dan angpau, kunjung-mengunjung.', '{"clueText": "Kad: Walaupun banyak perubahan, terdapat amalan yang terus kekal dalam masyarakat. Setiap kali menjelang perayaan ramai pulang ke tempat asal, pemberian duit raya atau angpau diteruskan, dan melawat jiran serta saudara kekal sebagai budaya.", "options": [{"text": "Balik ke kampung, pemberian duit raya dan angpau, kunjung-mengunjung.", "isCorrect": true}, {"text": "Kad ucapan melalui pos sahaja.", "isCorrect": false, "consequence": "Itu cara dahulu yang sudah berubah."}, {"text": "Makan besar hanya di restoran.", "isCorrect": false, "consequence": "Itu perubahan kini, bukan amalan kekal."}, {"text": "Penyediaan kuih dengan alat tradisional sahaja.", "isCorrect": false, "consequence": "Itu telah berubah kerana alat moden digunakan."}], "aftermath": "Kad tersalah baca dan cucu menyangka semua tradisi sudah hilang.", "turns": [{"after": 6, "options": [{"text": "Amalan itu mengeratkan perpaduan dan perlu diteruskan.", "isCorrect": true, "reaction": "Betul. Itulah warisan kita."}, {"text": "Amalan itu sudah ketinggalan zaman.", "isCorrect": false, "reaction": "Nenek tersinggung. Tradisi itu menyatukan keluarga."}, {"text": "Amalan itu hanya untuk kanak-kanak.", "isCorrect": false, "reaction": "Semua orang menyertai dan nenek ketawa kecil."}], "clue": "Teruskan amalan yang mengeratkan perpaduan."}]}'),
(618, 'e6_n3_s1', 'Kad Rumah Terbuka Malaysia', 'Baca kad dan tentukan enam perayaan Rumah Terbuka Malaysia.', '5', 'Mengenal pasti enam perayaan Rumah Terbuka Malaysia: Hari Raya Aidilfitri, Tahun Baharu Cina, Deepavali, Hari Gawai, Pesta Kaamatan dan Krismas.', '{"clueText": "Kad: Rumah terbuka ialah rumah yang dapat dikunjungi semua orang pada hari perayaan. Kerajaan Malaysia telah memutuskan enam perayaan sebagai perayaan utama yang dikenali sebagai Rumah Terbuka Malaysia.", "options": [{"text": "Aidilfitri, Tahun Baharu Cina, Deepavali, Hari Gawai, Pesta Kaamatan dan Krismas.", "isCorrect": true}, {"text": "Aidiladha, Thaipusam, Wesak, Vaisakhi, San Pedro dan Genggulang.", "isCorrect": false, "consequence": "Itu perayaan lain, tetapi bukan enam yang ditetapkan. Kad dikembalikan."}, {"text": "Aidilfitri, Krismas, Wesak, Vaisakhi, San Pedro dan Hari Moyang.", "isCorrect": false, "consequence": "Senarai itu tidak betul. Pelanggan mengerutkan dahi."}, {"text": "Tahon Baro, Jis Pai, Tawun Empai, Tahun Bahauk, Genggulang dan Hari Moyang.", "isCorrect": false, "consequence": "Itu perayaan Orang Asli. Pelanggan menggeleng."}], "aftermath": "Kad tersalah baca dan pelanggan salah faham tentang perayaan yang diraikan secara Rumah Terbuka. Pelanggan menegur.", "turns": [{"after": 6, "options": [{"text": "Rumah terbuka membolehkan semua kaum saling melawat dan mengeratkan perpaduan.", "isCorrect": true, "reaction": "Betul. Pelanggan tersenyum."}, {"text": "Rumah terbuka hanya untuk keluarga sendiri.", "isCorrect": false, "reaction": "Pelanggan membantah. Ia untuk semua orang."}, {"text": "Rumah terbuka tidak diperlukan.", "isCorrect": false, "reaction": "Pelanggan menggeleng kerana amalan itu mengeratkan perpaduan."}], "clue": "Rumah terbuka untuk semua."}]}'),
(619, 'e6_n3_s2', 'Kad Kepentingan Berkumpul', 'Baca kad dan tentukan kepentingan meraikan perayaan bersama keluarga.', '5', 'Memahami kepentingan meraikan perayaan bersama keluarga: mengeratkan hubungan, mengukuhkan perpaduan anggota keluarga, mengelakkan tradisi hilang, mengekalkan kesejahteraan negara.', '{"clueText": "Kad: Meraikan perayaan bersama keluarga dapat mengeratkan hubungan dan mengukuhkan perpaduan antara anggota keluarga, mengelakkan tradisi hilang ditelan zaman dan mengekalkan kesejahteraan negara.", "options": [{"text": "Mengeratkan hubungan keluarga dan mengelakkan tradisi hilang.", "isCorrect": true}, {"text": "Mengurangkan perhubungan antara keluarga.", "isCorrect": false, "consequence": "Jawapan itu bertentangan dengan kad."}, {"text": "Menambahkan tradisi baharu tanpa nilai.", "isCorrect": false, "consequence": "Tiada dalam kad. Pelanggan menggeleng."}, {"text": "Menggantikan perayaan dengan hari biasa.", "isCorrect": false, "consequence": "Itu menghilangkan tradisi. Kad dikembalikan."}], "aftermath": "Kad tersalah baca dan pelanggan menyangka berkumpul bersama keluarga tidak penting.", "turns": [{"after": 6, "options": [{"text": "Berkumpul bersama keluarga mengeratkan hubungan dan menjaga tradisi.", "isCorrect": true, "reaction": "Betul. Pelanggan membeli kad untuk semua jiran."}, {"text": "Cukup menelefon tanpa berjumpa.", "isCorrect": false, "reaction": "Hubungan menjadi renggang dan tradisi hilang."}, {"text": "Berkumpul hanya membazir masa.", "isCorrect": false, "reaction": "Pelanggan lain menegur kerana berkumpul penting untuk kesejahteraan."}], "clue": "Berkumpul untuk mengeratkan hubungan."}]}'),
(620, 'e6_n3_s3', 'Kad Hormat Kepelbagaian Sambutan', 'Baca kad dan tentukan kepentingan menghormati kepelbagaian sambutan dan adab perayaan.', '5', 'Memahami kepentingan: mengekalkan keamanan dan keharmonian negara, memupuk bertolak-ansur, melahirkan masyarakat yang memahami budaya kaum lain, melahirkan generasi rasional dan berilmu.', '{"clueText": "Kad: Menghormati kepelbagaian sambutan dan adab perayaan dapat mengekalkan keamanan dan keharmonian negara, memupuk semangat bertolak-ansur serta melahirkan masyarakat yang memahami dan menghormati budaya kaum lain.", "options": [{"text": "Mengekalkan keamanan dan keharmonian serta memupuk bertolak-ansur.", "isCorrect": true}, {"text": "Menimbulkan salah faham antara jiran.", "isCorrect": false, "consequence": "Kad menyatakan sebaliknya. Kau dibetulkan."}, {"text": "Menjauhkan satu kaum daripada yang lain.", "isCorrect": false, "consequence": "Itu menambah curiga. Kad dikembalikan."}, {"text": "Menyeragamkan semua perayaan menjadi satu.", "isCorrect": false, "consequence": "Kad tidak menyatakan begitu. Setiap perayaan ada keunikan."}], "aftermath": "Kad tersalah baca dan kanak-kanak melanggar adab semasa melawat. Jiran tersinggung.", "turns": [{"after": 6, "options": [{"text": "Kita bertanya tentang adab dan menghormati cara sambutan jiran.", "isCorrect": true, "reaction": "Itu cara yang matang."}, {"text": "Kita melawat tanpa bertanya.", "isCorrect": false, "reaction": "Jiran terasa tidak dihormati."}, {"text": "Kita tidak perlu melawat langsung.", "isCorrect": false, "reaction": "Hubungan menjadi renggang."}], "clue": "Tanya tentang adab dan hormati."}]}'),
(621, 'e6_n3_s4', 'Gawai dan Unduk Ngadau Dahulu dan Kini', 'Padankan cara sambutan dahulu dengan kini.', '4', 'Membezakan Hari Gawai dahulu (petani Dayak, upacara ritual) dengan kini (pelbagai kaum tanpa mengira pekerjaan), dan Unduk Ngadau dahulu (semangat Huminodun) dengan kini (soal jawab sejarah).', '{"pairs": [{"text": "Gawai dahulu", "pair": 1}, {"text": "Diraikan petani kaum Dayak dengan upacara ritual", "pair": 1}, {"text": "Gawai kini", "pair": 2}, {"text": "Diraikan pelbagai kaum tanpa mengira pekerjaan", "pair": 2}, {"text": "Unduk Ngadau dahulu", "pair": 3}, {"text": "Dipilih berdasarkan semangat Huminodun", "pair": 3}, {"text": "Unduk Ngadau kini", "pair": 4}, {"text": "Sesi soal jawab tentang sejarah dan kehidupan lampau", "pair": 4}], "aftermath": "Kad bertukar dan tetamu menyangka Gawai tidak berubah. Tetua menggeleng.", "turns": [{"after": 7, "options": [{"text": "Perayaan menjadi lebih meriah apabila semua kaum menyertainya dengan hormat.", "isCorrect": true, "reaction": "Betul. Tetua tersenyum."}, {"text": "Perayaan hanya boleh disertai kaum Dayak.", "isCorrect": false, "reaction": "Tetamu pulang dengan hampa."}, {"text": "Perayaan tidak perlu dipelihara kerana sudah berubah.", "isCorrect": false, "reaction": "Tetua menggeleng. Warisan perlu dijaga."}], "clue": "Perayaan disambut semua kaum dengan hormat."}]}'),
(622, 'e6_n3_s5', 'Pameran Tradisi Dahulu dan Kini', 'Padankan tradisi dahulu dengan perubahannya kini.', '4', 'Membezakan tradisi dahulu dan kini: kolam (tepung → beras atau hampas kelapa berwarna-warni), makan besar (di rumah → ada yang di restoran atau hotel), kuih (tradisional dan gotong-royong → peralatan moden).', '{"pairs": [{"text": "Kolam dibuat daripada tepung", "pair": 1}, {"text": "Beras atau hampas kelapa berwarna-warni", "pair": 1}, {"text": "Makan besar di rumah bersama keluarga", "pair": 2}, {"text": "Ada keluarga memilih restoran atau hotel", "pair": 2}, {"text": "Kuih bahan dan kaedah tradisional, gotong-royong", "pair": 3}, {"text": "Peralatan moden memudahkan penyediaan kuih", "pair": 3}], "aftermath": "Padanan tersilap dan pelanggan menyangka tradisi tiada perubahan. Pameran mengelirukan.", "turns": [{"after": 6, "options": [{"text": "Cara berubah mengikut zaman, tetapi tradisi dan semangatnya perlu dikekalkan.", "isCorrect": true, "reaction": "Betul. Pameran ini memberi pengajaran."}, {"text": "Tradisi lama patut ditinggalkan semuanya.", "isCorrect": false, "reaction": "Pelanggan tua tersinggung."}, {"text": "Tradisi tidak boleh berubah sama sekali.", "isCorrect": false, "reaction": "Pelanggan muda membantah kerana alat moden memudahkan."}], "clue": "Cara berubah, tradisi dikekalkan."}]}'),
(623, 'e6_n3_s6', 'Papan SWOT Warisan Perayaan', 'Padankan istilah SWOT dengan soalan yang dibincangkan.', '4', 'Memahami analisis SWOT tentang warisan perayaan: kekuatan, kelemahan, peluang, halangan dan cabaran untuk mengekalkan warisan.', '{"pairs": [{"text": "Kekuatan", "pair": 1}, {"text": "Apa yang membantu mengekalkan warisan perayaan", "pair": 1}, {"text": "Kelemahan", "pair": 2}, {"text": "Apa yang menyukarkan mempertahankan warisan perayaan", "pair": 2}, {"text": "Peluang", "pair": 3}, {"text": "Peluang untuk mengekalkan warisan perayaan", "pair": 3}, {"text": "Halangan dan cabaran", "pair": 4}, {"text": "Cabaran mengekalkan warisan perayaan", "pair": 4}], "aftermath": "Kad tersilap dan analisis kumpulan tidak menjawab soalan. Cikgu menggeleng.", "turns": [{"after": 6, "options": [{"text": "Kita menganalisis supaya dapat mengekalkan warisan perayaan.", "isCorrect": true, "reaction": "Betul. Murid-murid mula menulis."}, {"text": "Kita menganalisis supaya perayaan ditamatkan.", "isCorrect": false, "reaction": "Pekerja terkejut. Tujuannya mengekalkan warisan."}, {"text": "Kita tidak perlu menganalisis.", "isCorrect": false, "reaction": "Cikgu menggeleng kerana analisis membantu merancang."}], "clue": "Analisis SWOT membantu mengekalkan warisan."}]}'),
(624, 'e6_n3_s7', 'Ringkasan Amalan Perayaan', 'Padankan amalan dengan penerangannya.', '4', 'Merumus amalan yang kekal: balik ke kampung, pemberian duit raya dan angpau, kunjung-mengunjung, Rumah Terbuka.', '{"pairs": [{"text": "Balik ke kampung", "pair": 1}, {"text": "Tradisi menjelang perayaan yang kekal", "pair": 1}, {"text": "Duit raya dan angpau", "pair": 2}, {"text": "Pemberian yang kekal sehingga kini", "pair": 2}, {"text": "Kunjung-mengunjung", "pair": 3}, {"text": "Amalan budaya yang kekal dalam masyarakat", "pair": 3}, {"text": "Rumah terbuka", "pair": 4}, {"text": "Rumah yang dapat dikunjungi semua orang pada hari perayaan", "pair": 4}], "aftermath": "Kad tersilap dan ringkasan mengelirukan pelanggan terakhir.", "turns": [{"after": 6, "options": [{"text": "Perayaan yang dihormati mengeratkan perpaduan dan menjaga kesejahteraan negara.", "isCorrect": true, "reaction": "Betul. Kedai ditutup dengan senyuman."}, {"text": "Perayaan tidak berkaitan dengan perpaduan.", "isCorrect": false, "reaction": "Pelanggan menggeleng dan keluar."}, {"text": "Perayaan hanya membazir wang.", "isCorrect": false, "reaction": "Pelanggan tersinggung kerana perayaan mengeratkan hubungan."}], "clue": "Perayaan mengeratkan perpaduan."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e6_n1_s1', 'hint', 'Tahun Baharu Cina bermula pada hari pertama kalendar Cina. Kaamatan pada bulan Mei.', NULL, NULL),
(601, NULL, 'hint', 'Aidilfitri pada 1 Syawal, Aidiladha pada 10 Zulhijah. Krismas pada 25 Disember, Gawai pada 1 Jun.', 'Di bengkel kraf aku memadankan tarikh perayaan. Aidilfitri pada 1 Syawal, Aidiladha pada 10 Zulhijah, Tahun Baharu Cina pada hari pertama kalendar Cina, Krismas pada 25 Disember, Hari Gawai pada 1 Jun dan Pesta Kaamatan pada bulan Mei.', 'Tepat! Penggiat kraf menyusun semula kertas tempahan yang kering itu dan pesanan pertama siap dibungkus.'),
(NULL, 'e6_n1_s2', 'hint', 'Aidiladha bersama ibadah korban dan sedekah daging. Aidilfitri selepas berpuasa sebulan.', NULL, NULL),
(602, NULL, 'hint', 'Perayaan yang ada ibadah korban jatuh pada 10 Zulhijah dan diteruskan pada hari Tasyrik.', 'Aku belajar beza dua hari raya. Aidiladha disambut pada 10 Zulhijah dan diteruskan pada hari Tasyrik, dan umat Islam mengadakan ibadah korban serta memberikan sedekah daging, manakala Aidilfitri menandakan kegembiraan selepas berpuasa sebulan.', 'Betul! Aishah mengangguk lega dan memadam lakaran hiasan yang tersalah tadi.'),
(NULL, 'e6_n1_s3', 'hint', 'Selepas hari pertama, perayaan berlanjutan selama 15 hari.', NULL, NULL),
(603, NULL, 'hint', 'Mulakan dengan makan malam keluarga. Penutupnya hari Chap Goh Meh pada hari ke-15.', 'Ah Meng menerangkan susunan Tahun Baharu Cina. Malam sebelumnya seluruh keluarga berkumpul makan malam, hari pertama disambut pada hari pertama kalendar Cina, perayaan berlanjutan 15 hari, dan berakhir pada hari Chap Goh Meh.', 'Tepat! Ah Meng menampal kad urutan itu di dinding bengkel sambil tersenyum lebar.'),
(NULL, 'e6_n1_s4', 'hint', 'Dewa Murugan dalam Thaipusam. Gurdwara dalam Vaisakhi. Kolam dan pelita dalam Deepavali.', NULL, NULL),
(604, NULL, 'hint', 'Deepavali dengan kolam dan pelita. Thaipusam dengan pembayar niat. Vaisakhi dengan Gurdwara.', 'Kavitha dan Harjit menceritakan tiga perayaan. Deepavali menandakan kecerahan mengatasi kegelapan dengan kolam dan pelita, Thaipusam ialah masa pembayar niat membawa persembahan kepada Dewa Murugan, dan Vaisakhi ialah masa kaum Sikh bersembahyang di Gurdwara serta mensyukuri hasil tanaman.', 'Hebat! Kavitha dan Harjit saling berpandangan dan tersenyum puas apabila hiasan mereka dipadankan dengan betul.'),
(NULL, 'e6_n1_s5', 'hint', 'Sumazau dan Unduk Ngadau ialah sebahagian daripada Pesta Kaamatan.', NULL, NULL),
(605, NULL, 'hint', 'Gawai pada 1 Jun dengan ngajat. Kaamatan pada bulan Mei dengan Magavau, sumazau dan Unduk Ngadau.', 'Apai Jelani dan Linda menjelaskan dua pesta petani. Hari Gawai disambut kaum Dayak, Iban dan Bidayuh pada 1 Jun dengan ngajat di rumah panjang, manakala Pesta Kaamatan disambut kaum Kadazandusun dan Murut pada bulan Mei dengan Magavau, sumazau dan Unduk Ngadau.', 'Tepat sekali! Apai Jelani dan Linda bertepuk tangan dan berjanji menjemputmu ke pesta masing-masing.'),
(NULL, 'e6_n1_s6', 'hint', 'Mandi patung bermaksud penyucian diri. Karol ialah nyanyian gembira dari rumah ke rumah.', NULL, NULL),
(606, NULL, 'hint', 'Krismas bersama kelahiran Jesus Christ, hadiah dan karol. Wesak bersama tiga peristiwa hidup Siddharta Gautama.', 'Daniel dan Mei Ling menerangkan dua perayaan. Krismas memperingati kelahiran Jesus Christ dengan hadiah dan karol, manakala Hari Wesak dikaitkan dengan tiga peristiwa penting hidup Siddharta Gautama dan memandikan patung Buddha bermakna penyucian diri.', 'Bagus! Mei Ling tersenyum dan Daniel menyanyikan satu baris karol sebagai ucapan terima kasih.'),
(NULL, 'e6_n1_s7', 'hint', 'Hari Genggulang ialah doa suku Semai. Hari Moyang diraikan di Selangor dan Negeri Sembilan.', NULL, NULL),
(607, NULL, 'hint', 'Jakun menyebut Tahon Baro. Semai menyebut Jis Pai. Temuan menyebut Tahun Bahauk. Mah Meri menyebut Tawun Empai.', 'Tempahan dari kampung Orang Asli mengajarku nama sambutan tahun baharu mereka. Suku Jakun menyebutnya Tahon Baro, Semai menyebutnya Jis Pai, Temuan menyebutnya Tahun Bahauk dan Mah Meri menyebutnya Tawun Empai. Suku Semai juga meraikan Hari Genggulang, dan Orang Asli di Selangor serta Negeri Sembilan meraikan Hari Moyang.', 'Teliti! Penggiat Kraf menulis nama setiap suku pada tempahan itu dengan tulisan yang cantik.'),
(NULL, 'e6_n1_s8', 'hint', 'San Pedro ialah penaung nelayan. Tariannya ialah branyo.', NULL, NULL),
(608, NULL, 'hint', 'Perayaan nelayan berketurunan Portugis di Melaka bermula dengan huruf S, dan nama penaungnya sama.', 'Pak Nelayan menceritakan tentang San Pedro. Masyarakat berketurunan Portugis di Melaka meraikannya pada bulan Jun untuk penaung nelayan, dengan kapal dihias indah dan tarian branyo yang diwarisi sejak dahulu.', 'Betul! Pak Nelayan tersenyum bangga kerana perayaan masyarakatnya disebut dengan betul.'),
(NULL, 'e6_n2_s1', 'hint', 'Deepavali mengharapkan kebaikan mengatasi kejahatan. Wesak mengingati tokoh agama.', NULL, NULL),
(609, NULL, 'hint', 'Lima tujuan. Agama, tahun baharu, syukur hasil, kebaikan mengatasi kejahatan, dan mengingati tokoh agama.', 'Dalam perjalanan pulang aku belajar tujuan perayaan. Ada yang keagamaan, ada yang meraikan tahun baharu, ada yang mensyukuri hasil tanaman atau hasil laut, ada yang mengharapkan unsur baik mengatasi kejahatan seperti Deepavali, dan ada yang mengingati tokoh agama seperti Hari Wesak.', 'Tepat! Murid itu mencatat lima tujuan itu dalam telefonnya sambil mengangguk.'),
(NULL, 'e6_n2_s2', 'hint', 'Swafoto ialah gambar yang kita ambil sendiri bersama keluarga.', NULL, NULL),
(610, NULL, 'hint', 'Dahulu kad melalui pos dan foto di kedai gambar. Kini media sosial dan swafoto.', 'Nenek membandingkan cara dahulu dan kini. Dahulu kad ucapan dihantar melalui pos atau serahan tangan dan foto keluarga diambil di kedai gambar, tetapi kini ucapan dihantar melalui media elektronik dan media sosial dan kami swafoto lalu memuat naiknya.', 'Betul! Nenek tertawa kecil kerana cucunya akhirnya faham perbezaan kad dan skrin.'),
(NULL, 'e6_n2_s3', 'hint', 'Semua bukti berkait dengan kedai gambar zaman dahulu.', NULL, NULL),
(611, NULL, 'hint', 'Empat bukti. Kamera lama, latar lukisan studio, kerusi dan lampu studio.', 'Dalam gambar lama itu aku menjumpai empat bukti kedai gambar. Ada kamera lama, latar lukisan studio, kerusi untuk bergambar bersama keluarga dan lampu studio.', 'Mata yang tajam! Nenek membelai gambar itu dan bercerita lagi tentang zaman kecilnya.'),
(NULL, 'e6_n2_s4', 'hint', 'Kolam dahulu daripada tepung. Kolam kini daripada beras atau hampas kelapa.', NULL, NULL),
(612, NULL, 'hint', 'Empat bukti. Kolam daripada beras berwarna, kanak-kanak melukis, keluarga bersama dan pelita di tengah.', 'Kavitha menunjukkan kolam masa kini. Bahannya beras atau hampas kelapa yang berwarna-warni, kanak-kanak melukisnya beramai-ramai, keluarga duduk bersama membuatnya, dan pelita diletakkan di tengah kolam semasa Deepavali.', 'Cekap! Kavitha menepuk bahumu dan mengajakmu menyalakan pelita pertama.'),
(NULL, 'e6_n2_s5', 'hint', 'Nota itu menyebut tradisi yang masih diraikan dan tempat yang berubah.', NULL, NULL),
(613, NULL, 'hint', 'Tradisi makan besar masih ada. Cuma ada keluarga yang memilih restoran atau hotel.', 'Ah Meng dan nenek menerangkan perubahan makan besar. Tradisi berkumpul bersama keluarga pada malam Tahun Baharu Cina masih diraikan, walaupun ada keluarga yang memilih menikmatinya di restoran atau hotel.', 'Tepat! Ah Meng mengangguk lega kerana datuknya tidak lagi berkecil hati.'),
(NULL, 'e6_n2_s6', 'hint', 'Kerja bersama oleh jiran dan keluarga dinamakan gotong-royong.', NULL, NULL),
(614, NULL, 'hint', 'Kuih dahulu dibuat dengan bahan dan kaedah tradisional oleh jiran dan keluarga bersama-sama.', 'Nenek bercerita tentang penyediaan kuih dahulu. Kuih dibuat menggunakan bahan dan kaedah tradisional, dan kerja itu dilakukan secara gotong-royong oleh jiran dan keluarga.', 'Betul! Nenek tersenyum sambil menghulur adunan kepadamu untuk dibentuk.'),
(NULL, 'e6_n2_s7', 'hint', 'Semua bukti menunjukkan kuih raya kini mudah dibeli.', NULL, NULL),
(615, NULL, 'hint', 'Empat bukti. Rak balang kuih, juruwang, hamper kuih dan papan Selamat Hari Raya.', 'Di kedai itu aku menjumpai empat bukti kuih raya kini mudah dibeli. Ada rak balang kuih, juruwang, beg hadiah dan hamper yang siap dibungkus, serta papan Selamat Hari Raya.', 'Cekap! Nenek mengangguk sambil memilih sebalang kuih untuk dibawa pulang.'),
(NULL, 'e6_n2_s8', 'hint', 'Pemenang dahulu dipilih berdasarkan semangat Huminodun.', NULL, NULL),
(616, NULL, 'hint', 'Empat bukti. Pemenang Unduk Ngadau, tiga peserta, pentas pondok dan sawah padi.', 'Linda menceritakan Unduk Ngadau. Dahulu pemenang dipilih berdasarkan semangat Huminodun, iaitu kesanggupan berkorban untuk menyelamatkan generasinya, tetapi kini dipilih berdasarkan sesi soal jawab tentang sejarah dan kehidupan lampau. Sawah padi dan pentas pondok masih menjadi latarnya.', 'Hebat! Linda tersenyum bangga kerana kau mengenal empat petunjuk warisan pestanya.'),
(NULL, 'e6_n2_s9', 'hint', 'Kunjung-mengunjung ialah melawat jiran dan saudara.', NULL, NULL),
(617, NULL, 'hint', 'Tiga amalan kekal. Balik ke kampung, duit raya dan angpau, dan melawat jiran serta saudara.', 'Nenek menerangkan amalan yang kekal. Tradisi balik ke kampung, pemberian duit raya dan angpau, serta kunjung-mengunjung melawat jiran dan saudara terus dilakukan walaupun banyak perkara sudah berubah.', 'Betul, nak! Nenek menghulurkan sampul kecil dengan senyuman sebagai tanda amalan itu masih hidup.'),
(NULL, 'e6_n3_s1', 'hint', 'Aidilfitri, Tahun Baharu Cina dan Deepavali. Selebihnya ialah Gawai, Kaamatan dan Krismas.', NULL, NULL),
(618, NULL, 'hint', 'Rumah terbuka boleh dikunjungi semua orang. Enam perayaan itu termasuk Gawai dan Kaamatan.', 'Di kedai itu aku mengetahui bahawa rumah terbuka dapat dikunjungi semua orang pada hari perayaan. Kerajaan memutuskan enam perayaan utama sebagai Rumah Terbuka Malaysia, iaitu Aidilfitri, Tahun Baharu Cina, Deepavali, Hari Gawai, Pesta Kaamatan dan Krismas.', 'Tepat! Peniaga menulis enam perayaan itu di papan tulis kecil di pintu kedainya.'),
(NULL, 'e6_n3_s2', 'hint', 'Kad itu menyebut hubungan keluarga, perpaduan, tradisi dan kesejahteraan negara.', NULL, NULL),
(619, NULL, 'hint', 'Berkumpul mengeratkan hubungan dan mengelakkan tradisi hilang ditelan zaman.', 'Peniaga mengajarku kepentingan meraikan perayaan bersama keluarga. Ia mengeratkan hubungan dan mengukuhkan perpaduan antara anggota keluarga, mengelakkan tradisi hilang ditelan zaman dan mengekalkan kesejahteraan negara.', 'Betul! Aishah mengangguk dan menulis jawapan itu dalam buku nota anaknya.'),
(NULL, 'e6_n3_s3', 'hint', 'Bertolak-ansur bermaksud saling memahami dan menghormati.', NULL, NULL),
(620, NULL, 'hint', 'Hormat kepada adab perayaan mengekalkan keamanan dan keharmonian serta memupuk bertolak-ansur.', 'Ah Meng bertanya tentang adab melawat jiran, dan peniaga menjelaskan bahawa menghormati kepelbagaian sambutan dan adab perayaan mengekalkan keamanan dan keharmonian, memupuk semangat bertolak-ansur dan melahirkan masyarakat yang menghormati budaya kaum lain.', 'Tepat! Ah Meng menulis soalan adab itu dalam telefonnya sebelum bertandang ke rumah jirannya.'),
(NULL, 'e6_n3_s4', 'hint', 'Dahulu Unduk Ngadau berasaskan semangat Huminodun. Kini ia sesi soal jawab.', NULL, NULL),
(621, NULL, 'hint', 'Gawai dahulu untuk petani Dayak dengan upacara ritual. Gawai kini untuk pelbagai kaum. Unduk Ngadau kini ada soal jawab sejarah.', 'Apai Jelani membandingkan Gawai dahulu dengan kini. Dahulu Gawai diraikan petani Dayak dengan upacara ritual, kini diraikan pelbagai kaum tanpa mengira pekerjaan. Pemenang Unduk Ngadau dahulu dipilih berdasarkan semangat Huminodun, kini melalui sesi soal jawab tentang sejarah dan kehidupan lampau.', 'Betul! Apai Jelani tersenyum puas kerana tetamu dari pelbagai kaum menyertai pestanya dengan hormat.'),
(NULL, 'e6_n3_s5', 'hint', 'Perubahan kini ialah beras berwarna, restoran atau hotel, dan peralatan moden.', NULL, NULL),
(622, NULL, 'hint', 'Kolam dahulu daripada tepung. Makan besar dahulu di rumah. Kuih dahulu secara gotong-royong.', 'Aku menyusun tradisi dahulu dengan perubahannya. Kolam daripada tepung kini daripada beras atau hampas kelapa berwarna-warni, makan besar di rumah kini ada yang di restoran atau hotel, dan kuih tradisional secara gotong-royong kini dibantu peralatan moden.', 'Tepat! Pameran kecil itu kini lengkap dan pelanggan berhenti untuk membacanya.'),
(NULL, 'e6_n3_s6', 'hint', 'Empat istilah SWOT ialah kekuatan, kelemahan, peluang, dan halangan atau cabaran.', NULL, NULL),
(623, NULL, 'hint', 'Kekuatan membantu. Kelemahan menyukarkan. Peluang untuk mengekalkan. Halangan ialah cabaran.', 'Peniaga mengajar analisis SWOT warisan perayaan. Kekuatan membantu mengekalkan warisan, kelemahan menyukarkan mempertahankannya, peluang ialah peluang mengekalkannya, dan halangan serta cabaran ialah cabaran mengekalkannya.', 'Hebat! Murid itu menyalin empat istilah itu di buku latihannya dengan hati-hati.'),
(NULL, 'e6_n3_s7', 'hint', 'Rumah terbuka boleh dikunjungi semua orang pada hari perayaan.', NULL, NULL),
(624, NULL, 'hint', 'Balik ke kampung, duit raya dan angpau, kunjung-mengunjung, dan rumah terbuka.', 'Kedai ditutup dengan rumusan. Balik ke kampung, pemberian duit raya dan angpau, serta kunjung-mengunjung kekal sebagai amalan, dan rumah terbuka ialah rumah yang dapat dikunjungi semua orang pada hari perayaan.', 'Tahniah! Peniaga menutup kedai dengan senyuman dan menyerahkan hamper kecil kepadamu sebagai kenang-kenangan.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(101, 601, NULL, 'Tugasku ialah membuat hiasan untuk semua perayaan. Jika aku tersilap hiasan atau tarikh, pelanggan akan berasa perayaan mereka tidak dihormati, {nama}.', 1),
(101, 601, NULL, 'Aku belajar bahawa perayaan disambut penuh muhibah dan kita wajar menghormati perayaan kaum lain demi masyarakat yang harmoni.', 2),
(101, 601, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penggiat kraf yang membuat hiasan perayaan. Dengar tempahan pelanggan dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(101, 601, 'e6_n1_s1', 'Musim perayaan sudah dekat, dan bengkel ini dibanjiri tempahan hiasan. Tetapi hujan menembusi atap semalam, dan kertas tarikh pada setiap tempahan basah lunyai.', 1),
(104, 601, 'e6_n1_s1', 'Aku menempah hiasan Aidilfitri. Aidilfitri disambut pada 1 Syawal mengikut kalendar Islam, selepas sebulan berpuasa.', 2),
(104, 601, 'e6_n1_s1', 'Dan Hari Raya Aidiladha pula pada 10 Zulhijah mengikut kalendar Islam. Jangan tertukar dengan Aidilfitri, ya.', 3),
(106, 601, 'e6_n1_s1', 'Tahun Baharu Cina kami pada hari pertama dalam kalendar Cina. Tanglung merah itu mesti siap sebelum itu.', 4),
(108, 601, 'e6_n1_s1', 'Krismas pada 25 Disember setiap tahun. Jangan tertukar dengan Gawai, kerana Gawai hanya pada 1 Jun.', 5),
(109, 601, 'e6_n1_s1', 'Pesta Kaamatan pula disambut pada bulan Mei setiap tahun.', 6),
(NULL, 601, 'e6_n1_s1', 'Aku akan padankan semuanya dengan tarikh sebelum hiasan dihantar.', 7),
(101, 601, 'e6_n1_s1', 'Baguslah. Tetapi kenapa kita perlu berhati-hati dengan tarikh dan makna setiap perayaan, bukan sekadar menyiapkan hiasan?', 8),
(104, 601, 'e6_n1_s2', 'Penggiat Kraf, aku masih keliru antara Aidilfitri dan Aidiladha. Apa bezanya sebenarnya?', 1),
(113, 601, 'e6_n1_s2', 'Kawan saya kata dua-duanya hari raya untuk bergembira sahaja.', 2),
(101, 601, 'e6_n1_s2', 'Tidak begitu. Aidiladha disambut oleh masyarakat Islam pada 10 Zulhijah, dan diteruskan pada hari Tasyrik, iaitu 11, 12 dan 13 Zulhijah.', 3),
(101, 601, 'e6_n1_s2', 'Pada hari-hari itu umat Islam mengadakan ibadah korban dan memberikan sedekah daging korban. Aidilfitri tidak begitu.', 4),
(NULL, 601, 'e6_n1_s2', 'Kad di kaunter ini pun menyebut perkara yang sama. Perayaan yang melibatkan ibadah korban ialah Hari Raya Aidiladha.', 5),
(104, 601, 'e6_n1_s2', 'Betul. Tetapi kalau kita membuat hiasan yang sama untuk kedua-duanya, adakah itu sesuai?', 6),
(106, 601, 'e6_n1_s3', 'Tahun Baharu Cina bermula pada malam sebelum hari pertama, apabila seluruh ahli keluarga berkumpul untuk makan malam bersama-sama.', 1),
(107, 601, 'e6_n1_s3', 'Kata nenekku, selepas itu perayaan berlanjutan selama 15 hari dengan sambutan di rumah dan tempat awam.', 2),
(106, 601, 'e6_n1_s3', 'Hari pertama ialah apabila Tahun Baharu Cina disambut pada hari pertama dalam kalendar Cina. Pada hari ke-15, perayaan berakhir pada hari Chap Goh Meh.', 3),
(NULL, 601, 'e6_n1_s3', 'Malam sebelum itu, hari pertama, selama 15 hari, dan hari ke-15. Aku akan susun kad ini mengikut urutan.', 4),
(106, 601, 'e6_n1_s3', 'Jika silap, keluarga akan terlepas hari penting. Jadi apa sebenarnya yang diraikan dalam perayaan ini?', 5),
(105, 601, 'e6_n1_s4', 'Deepavali disambut pada bulan Aippasi mengikut kalendar masyarakat Hindu. Kami menghias rumah dengan kolam dan menyalakan pelita.', 1),
(105, 601, 'e6_n1_s4', 'Maknanya, kecerahan mengatasi kegelapan, atau kebijaksanaan mengatasi kejahilan.', 2),
(105, 601, 'e6_n1_s4', 'Thaipusam pula pada bulan ke-10 kalendar Hindu. Pembayar niat membawa persembahan kepada Dewa Murugan sebagai tanda terima kasih atau meminta hajat.', 3),
(110, 601, 'e6_n1_s4', 'Vaisakhi disambut oleh kaum Sikh pada bulan keempat, Vaisakh. Kami bersembahyang di Gurdwara dan mensyukuri hasil tanaman.', 4),
(NULL, 601, 'e6_n1_s4', 'Deepavali dengan kolam dan pelita, Thaipusam dengan pembayar niat, dan Vaisakhi dengan sembahyang di Gurdwara. Aku akan padankan semuanya.', 5),
(101, 601, 'e6_n1_s4', 'Cantik. Tetapi kenapa hiasan setiap perayaan mesti sesuai dengan maknanya?', 6),
(111, 601, 'e6_n1_s5', 'Hari Gawai kami disambut pada 1 Jun oleh kaum Dayak, Iban dan Bidayuh. Kami bersyukur atas hasil tani, dan ngajat ditarikan di rumah panjang.', 1),
(109, 601, 'e6_n1_s5', 'Pesta Kaamatan pula disambut oleh kaum Kadazandusun dan Murut pada bulan Mei. Bobohizan mengetuai upacara Magavau.', 2),
(109, 601, 'e6_n1_s5', 'Tarian sumazau dan pertandingan Unduk Ngadau pula memeriahkan Pesta Kaamatan.', 3),
(111, 601, 'e6_n1_s5', 'Jangan campur-adukkan, kerana Gawai bukan Kaamatan.', 4),
(NULL, 601, 'e6_n1_s5', 'Gawai dengan ngajat di rumah panjang, Kaamatan dengan Magavau, sumazau dan Unduk Ngadau. Aku akan padankan kad ini.', 5),
(109, 601, 'e6_n1_s5', 'Betul. Kedua-duanya perayaan kaum petani, tetapi apakah yang sama dan apakah yang berbeza antara keduanya?', 6),
(108, 601, 'e6_n1_s6', 'Krismas disambut pada 25 Disember. Kami memperingati kelahiran Jesus Christ, dan memberi hadiah serta menyanyi karol dari rumah ke rumah.', 1),
(107, 601, 'e6_n1_s6', 'Karol ialah nyanyian gembira atau puji-pujian semasa Krismas. Hari Wesak pula pada bulan Mei, dan kami memandikan patung Buddha Siddharta.', 2),
(107, 601, 'e6_n1_s6', 'Wesak dikaitkan dengan tiga peristiwa penting dalam hidup Siddharta Gautama, iaitu hari kelahiran, hari mencapai kesempurnaan fikiran dan hari nirwananya.', 3),
(113, 601, 'e6_n1_s6', 'Tetapi mengapa kita memandikan patung Buddha? Apa maknanya?', 4),
(107, 601, 'e6_n1_s6', 'Memandikan patung itu bermakna penyucian diri. Selepas itu kami mengagihkan makanan kepada sami.', 5),
(NULL, 601, 'e6_n1_s6', 'Aku akan padankan Krismas, Wesak, mandi patung dan karol dengan maknanya.', 6),
(113, 601, 'e6_n1_s6', 'Baik. Jadi bagaimana boleh kita jelaskan maksud memandikan patung Buddha kepada kawan yang bertanya?', 7),
(101, 601, 'e6_n1_s7', 'Kali ini tempahan datang dari kampung Orang Asli. Mereka mahu hiasan tahun baharu, tetapi setiap suku menyebutnya dengan nama berbeza.', 1),
(101, 601, 'e6_n1_s7', 'Suku Jakun menyebutnya Tahon Baro, dan suku Semai menyebutnya Jis Pai. Suku Temuan pula mengenalinya sebagai Tahun Bahauk.', 2),
(101, 601, 'e6_n1_s7', 'Suku Mah Meri menyebutnya Tawun Empai. Sambutan ini bermula pada 31 Disember setiap tahun.', 3),
(113, 601, 'e6_n1_s7', 'Cikgu pernah kata suku Semai ada perayaan lain juga. Apa namanya?', 4),
(101, 601, 'e6_n1_s7', 'Suku Semai meraikan Hari Genggulang dengan berdoa agar wujud kesejahteraan di kampung. Orang Asli di Selangor dan Negeri Sembilan pula meraikan Hari Moyang.', 5),
(NULL, 601, 'e6_n1_s7', 'Jakun, Semai, Temuan dan Mah Meri dengan nama tahun baharu masing-masing, serta Genggulang dan Hari Moyang. Aku akan padankan semuanya.', 6),
(101, 601, 'e6_n1_s7', 'Teliti ya. Tetapi kenapa setiap suku perlu dihormati dengan nama sambutan mereka sendiri?', 7),
(114, 601, 'e6_n1_s8', 'Setiap Jun, kapal kami dihias indah. Tahukah kamu perayaan apa ini?', 1),
(113, 601, 'e6_n1_s8', 'Pakcik nelayan, saya dengar perayaan ini ada penaung. Siapa dia?', 2),
(114, 601, 'e6_n1_s8', 'Perayaan ini disambut oleh masyarakat berketurunan Portugis di Melaka pada bulan Jun setiap tahun. Kami meraikan penaung nelayan.', 3),
(114, 601, 'e6_n1_s8', 'Tarian branyo yang diwarisi sejak dahulu ditarikan pada hari itu.', 4),
(NULL, 601, 'e6_n1_s8', 'Papan perayaan ini pun menyebutnya. Kapal dihias indah dan branyo ditarikan. Perayaan itu ialah San Pedro.', 5),
(114, 601, 'e6_n1_s8', 'Betul. Tetapi bagaimana kita patut melayan perayaan masyarakat lain seperti ini, apabila datang ke pelabuhan ini?', 6),
(102, 602, NULL, 'Tugasku ialah membawa anak-anak pulang beraya dan membandingkan cara dahulu dengan cara kini, supaya mereka tahu tradisi tidak hilang, {nama}.', 1),
(102, 602, NULL, 'Aku belajar bahawa cara sambutan perayaan berubah, tetapi amalan seperti balik kampung, duit raya dan kunjung-mengunjung kekal sehingga kini.', 2),
(102, 602, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, ibu moden yang pulang beraya ke kampung. Dengar cerita nenek dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(113, 602, 'e6_n2_s1', 'Mak, mengapa kita ada banyak perayaan di Malaysia? Tujuannya sama ke?', 1),
(102, 602, 'e6_n2_s1', 'Tidak sama, nak. Ada perayaan keagamaan, seperti Aidilfitri, Aidiladha, Krismas dan Thaipusam.', 2),
(112, 602, 'e6_n2_s1', 'Ada perayaan meraikan tahun baharu, seperti Tahun Baharu Cina, Tahon Baro, Jis Pai dan Tawun Empai.', 3),
(112, 602, 'e6_n2_s1', 'Ada perayaan mensyukuri hasil tanaman atau hasil laut, seperti Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro.', 4),
(102, 602, 'e6_n2_s1', 'Deepavali pula mengharapkan unsur baik mengatasi kejahatan. Hari Wesak mengingati tokoh agama.', 5),
(NULL, 602, 'e6_n2_s1', 'Aku akan padankan lima tujuan itu dengan perayaan masing-masing.', 6),
(113, 602, 'e6_n2_s1', 'Kalau tersilap, saya akan beritahu kawan perkara yang salah. Jadi kenapa kita patut menghormati cara sambutan yang berbeza?', 7),
(113, 602, 'e6_n2_s2', 'Nenek, kenapa dahulu hantar kad? Kini cukup tekan butang sahaja.', 1),
(112, 602, 'e6_n2_s2', 'Dahulu kad ucapan dihantar melalui pos atau diserahkan sendiri. Kami menunggu berhari-hari.', 2),
(102, 602, 'e6_n2_s2', 'Sekarang ucapan dihantar melalui media elektronik dan media sosial, dalam sekelip mata.', 3),
(112, 602, 'e6_n2_s2', 'Dahulu juga kami mengambil foto keluarga di kedai gambar. Pak jurugambar yang atur kedudukan kami.', 4),
(102, 602, 'e6_n2_s2', 'Sekarang kami swafoto bersama keluarga, lalu dimuat naik di media sosial.', 5),
(NULL, 602, 'e6_n2_s2', 'Aku akan padankan cara ucapan dan foto dahulu dengan kini.', 6),
(112, 602, 'e6_n2_s2', 'Jangan terbalik, nanti cucu salah faham. Jadi apakah yang masih sama walaupun caranya sudah berubah?', 7),
(112, 602, 'e6_n2_s3', 'Dahulu kami bergambar di kedai gambar dengan kamera yang besar.', 1),
(113, 602, 'e6_n2_s3', 'Mana buktinya, Nenek? Gambar lama ini kabur.', 2),
(112, 602, 'e6_n2_s3', 'Lihat betul-betul. Ada kamera lama untuk mengambil foto keluarga, latar lukisan studio di belakang, dan kerusi untuk bergambar bersama.', 3),
(112, 602, 'e6_n2_s3', 'Lampu studio pun masih kelihatan di sudut itu. Itulah bukti cara kami bergambar dahulu.', 4),
(NULL, 602, 'e6_n2_s3', 'Kamera lama, latar lukisan studio, kerusi dan lampu studio. Aku akan cari keempat-empatnya dalam gambar.', 5),
(112, 602, 'e6_n2_s3', 'Teliti, cucu. Selepas kau menjumpai semuanya, apakah yang boleh kita lakukan terhadap gambar lama ini?', 6),
(105, 602, 'e6_n2_s4', 'Kolam kami kini dibuat dengan beras atau hampas kelapa yang berwarna-warni.', 1),
(112, 602, 'e6_n2_s4', 'Dahulu kolam dibuat daripada tepung.', 2),
(113, 602, 'e6_n2_s4', 'Mana satu kolam yang betul pada masa kini?', 3),
(105, 602, 'e6_n2_s4', 'Cari dalam gambar ini. Kanak-kanak melukis kolam beramai-ramai, dan keluarga duduk bersama membuat kolam pada Deepavali.', 4),
(105, 602, 'e6_n2_s4', 'Dan lihat, ada pelita di tengah kolam semasa Deepavali.', 5),
(NULL, 602, 'e6_n2_s4', 'Beras berwarna-warni, kanak-kanak melukis, keluarga duduk bersama, dan pelita di tengah. Aku akan cari keempat-empatnya.', 6),
(105, 602, 'e6_n2_s4', 'Baik. Tetapi bahannya sudah berubah. Apakah yang tidak berubah?', 7),
(106, 602, 'e6_n2_s5', 'Dulu datuk makan besar di rumah. Kini keluarga kami ke restoran. Salahkah?', 1),
(112, 602, 'e6_n2_s5', 'Tidak salah. Tradisi makan besar di rumah, dengan berkumpul bersama keluarga pada malam Tahun Baharu Cina, masih diraikan.', 2),
(112, 602, 'e6_n2_s5', 'Walau bagaimanapun, ada keluarga yang memilih untuk menikmatinya di tempat lain, seperti restoran atau hotel.', 3),
(NULL, 602, 'e6_n2_s5', 'Nota ini pun menyebut perkara itu. Tradisi masih diraikan, tetapi ada keluarga memilih restoran atau hotel.', 4),
(106, 602, 'e6_n2_s5', 'Betul. Tetapi supaya datukku tidak berkecil hati, apakah yang patut kita kekalkan walaupun tempatnya sudah berubah?', 5),
(113, 602, 'e6_n2_s6', 'Nek, kenapa tidak beli sahaja kuih raya? Kan lebih senang.', 1),
(112, 602, 'e6_n2_s6', 'Dahulu kuih dibuat dengan bahan dan kaedah tradisional. Kerja itu dilakukan secara gotong-royong oleh jiran dan keluarga.', 2),
(102, 602, 'e6_n2_s6', 'Seluruh rumah berbau mentega, dan anak-anak membantu membentuk kuih.', 3),
(NULL, 602, 'e6_n2_s6', 'Kad ini pun menyebut perkara yang sama. Penyediaan kuih dahulu menggunakan bahan dan kaedah tradisional secara gotong-royong.', 4),
(112, 602, 'e6_n2_s6', 'Itulah dia. Jadi apakah yang kita dapat daripada kerja gotong-royong itu?', 5),
(113, 602, 'e6_n2_s7', 'Nek, kuih ini beli sahaja di kedai. Adakah tradisi sudah hilang?', 1),
(112, 602, 'e6_n2_s7', 'Tidak hilang. Kini peralatan moden memudahkan penyediaan kuih, dan kuih raya juga mudah dibeli.', 2),
(102, 602, 'e6_n2_s7', 'Lihat di kedai itu. Ada rak balang kuih raya, juruwang yang melayan pelanggan, beg hadiah dan hamper kuih yang siap dibungkus.', 3),
(102, 602, 'e6_n2_s7', 'Di pintu pula ada papan Selamat Hari Raya.', 4),
(NULL, 602, 'e6_n2_s7', 'Rak balang kuih, juruwang, hamper kuih dan papan ucapan. Aku akan cari keempat-empatnya.', 5),
(113, 602, 'e6_n2_s7', 'Cepat, kedai nak tutup. Tetapi walaupun kuih dibeli, apakah yang masih kekal dalam perayaan?', 6),
(109, 602, 'e6_n2_s8', 'Dahulu pemenang Unduk Ngadau dipilih berdasarkan semangat Huminodun, iaitu kesanggupan berkorban untuk menyelamatkan generasinya.', 1),
(113, 602, 'e6_n2_s8', 'Dan kini bagaimana, Kak Linda?', 2),
(109, 602, 'e6_n2_s8', 'Kini pemenang dipilih berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.', 3),
(NULL, 602, 'e6_n2_s8', 'Dalam gambar ini ada pemenang Unduk Ngadau dahulu, tiga peserta yang menunggu keputusan, pentas pondok di tepi sawah, dan sawah padi yang disyukuri. Aku akan mencari keempat-empatnya.', 4),
(109, 602, 'e6_n2_s8', 'Teliti, kerana ini warisan kami. Tetapi walaupun cara memilih sudah berubah, apakah nilai yang masih kekal?', 5),
(113, 602, 'e6_n2_s9', 'Nek, apa yang tidak berubah dari dahulu hingga sekarang?', 1),
(112, 602, 'e6_n2_s9', 'Banyak, nak. Setiap kali menjelang perayaan, ramai yang pulang ke tempat asal. Itulah tradisi balik ke kampung.', 2),
(102, 602, 'e6_n2_s9', 'Pemberian duit raya dan angpau pun diteruskan sehingga kini.', 3),
(112, 602, 'e6_n2_s9', 'Dan melawat jiran serta saudara kekal sebagai budaya. Orang kampung memanggilnya kunjung-mengunjung.', 4),
(NULL, 602, 'e6_n2_s9', 'Kad ini pun menyebutnya. Balik ke kampung, pemberian duit raya dan angpau, dan kunjung-mengunjung kekal dalam masyarakat.', 5),
(112, 602, 'e6_n2_s9', 'Pilih dengan teliti. Selepas ini, apakah yang amalan itu lakukan kepada perpaduan kita?', 6),
(103, 603, NULL, 'Tugasku ialah melayan pelanggan semua kaum dengan hormat. Jika aku tersilap, perayaan mereka akan tersinggung, {nama}.', 1),
(103, 603, NULL, 'Aku belajar bahawa menghormati kepelbagaian sambutan perayaan mengekalkan keamanan dan keharmonian negara.', 2),
(103, 603, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, peniaga rumah kedai yang menjual keperluan semua perayaan. Layan setiap pelanggan dengan hormat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(104, 603, 'e6_n3_s1', 'Pakcik Peniaga, apakah perayaan yang diraikan melalui Rumah Terbuka Malaysia?', 1),
(103, 603, 'e6_n3_s1', 'Rumah terbuka ialah rumah yang dapat dikunjungi semua orang pada hari perayaan. Kerajaan Malaysia telah memutuskan enam perayaan utama sebagai Rumah Terbuka Malaysia.', 2),
(106, 603, 'e6_n3_s1', 'Aku dengar ada enam, tetapi tak ingat semuanya.', 3),
(103, 603, 'e6_n3_s1', 'Aidilfitri, Tahun Baharu Cina dan Deepavali. Kemudian Hari Gawai, Pesta Kaamatan dan Krismas.', 4),
(NULL, 603, 'e6_n3_s1', 'Kad ini pun menyebut senarai itu. Aku akan tentukan yang betul.', 5),
(104, 603, 'e6_n3_s1', 'Jangan tersilap, nanti pelanggan lain kecewa. Jadi bagaimana rumah terbuka membantu kita semua?', 6),
(104, 603, 'e6_n3_s2', 'Mengapa kita perlu meraikan perayaan bersama keluarga?', 1),
(113, 603, 'e6_n3_s2', 'Hanya telefon sahaja pun cukup, bukan?', 2),
(103, 603, 'e6_n3_s2', 'Meraikan perayaan bersama keluarga dapat mengeratkan hubungan dan mengukuhkan perpaduan antara anggota keluarga.', 3),
(103, 603, 'e6_n3_s2', 'Ia juga mengelakkan tradisi hilang ditelan zaman dan mengekalkan kesejahteraan negara.', 4),
(NULL, 603, 'e6_n3_s2', 'Kad ini pun menyebut perkara itu. Aku akan tentukan kepentingan meraikan perayaan bersama keluarga.', 5),
(104, 603, 'e6_n3_s2', 'Jawab betul-betul, kerana aku mahu ajar anakku. Jadi, kalau keluarga kita jauh, apa yang patut kita usahakan?', 6),
(106, 603, 'e6_n3_s3', 'Aku mahu melawat rumah jiran Melayu pada hari raya. Bagaimana adabnya?', 1),
(103, 603, 'e6_n3_s3', 'Setiap perayaan ada adab tersendiri. Jadi kita bertanya dahulu sebelum bertandang.', 2),
(103, 603, 'e6_n3_s3', 'Menghormati kepelbagaian sambutan dan adab perayaan dapat mengekalkan keamanan dan keharmonian negara.', 3),
(103, 603, 'e6_n3_s3', 'Ia juga memupuk semangat bertolak-ansur serta melahirkan masyarakat yang memahami dan menghormati budaya kaum lain.', 4),
(NULL, 603, 'e6_n3_s3', 'Kad ini pun menyebutnya. Aku akan tentukan kepentingan menghormati kepelbagaian sambutan dan adab perayaan.', 5),
(106, 603, 'e6_n3_s3', 'Baik. Aku mahu elakkan salah faham, jadi apa yang patut aku lakukan sebelum bertandang ke rumah jiran?', 6),
(111, 603, 'e6_n3_s4', 'Dahulu Hari Gawai diraikan oleh petani kaum Dayak dengan upacara ritual. Kini ramai tetamu datang.', 1),
(106, 603, 'e6_n3_s4', 'Aku datang kerana jiranku jemput, tetapi aku keliru dengan caranya.', 2),
(111, 603, 'e6_n3_s4', 'Kini Hari Gawai diraikan oleh pelbagai kaum tanpa mengira pekerjaan.', 3),
(113, 603, 'e6_n3_s4', 'Dan Unduk Ngadau? Dahulu pemenangnya dipilih berdasarkan semangat Huminodun.', 4),
(111, 603, 'e6_n3_s4', 'Kini pemenang dipilih melalui sesi soal jawab tentang sejarah dan kehidupan lampau.', 5),
(NULL, 603, 'e6_n3_s4', 'Aku akan padankan sambutan Gawai dan Unduk Ngadau dahulu dengan kini.', 6),
(111, 603, 'e6_n3_s4', 'Betulkan, supaya tetamu faham. Dan kenapa perayaan semakin meriah apabila semua kaum menyertainya?', 7),
(113, 603, 'e6_n3_s5', 'Mana satu cara dahulu dan mana satu cara kini?', 1),
(105, 603, 'e6_n3_s5', 'Aku tahu kolam dahulu dibuat daripada tepung. Kini ia daripada beras atau hampas kelapa berwarna-warni.', 2),
(106, 603, 'e6_n3_s5', 'Makan besar dahulu di rumah bersama keluarga. Kini ada keluarga memilih restoran atau hotel.', 3),
(103, 603, 'e6_n3_s5', 'Kuih dahulu dibuat dengan bahan dan kaedah tradisional secara gotong-royong. Kini peralatan moden memudahkan penyediaan kuih.', 4),
(NULL, 603, 'e6_n3_s5', 'Aku akan padankan setiap tradisi dengan perubahannya.', 5),
(103, 603, 'e6_n3_s5', 'Betul. Cara berubah mengikut zaman. Tetapi apa yang patut kita kekalkan?', 6),
(113, 603, 'e6_n3_s6', 'Cikgu kata kita perlu membuat analisis SWOT tentang warisan perayaan. Apa itu?', 1),
(103, 603, 'e6_n3_s6', 'Empat bahagian. Kekuatan ialah apa yang membantu mengekalkan warisan perayaan.', 2),
(103, 603, 'e6_n3_s6', 'Kelemahan ialah apa yang menyukarkan mempertahankan warisan perayaan. Peluang ialah peluang untuk mengekalkannya.', 3),
(103, 603, 'e6_n3_s6', 'Halangan dan cabaran ialah cabaran dalam mengekalkan warisan perayaan.', 4),
(NULL, 603, 'e6_n3_s6', 'Aku akan padankan setiap istilah SWOT dengan soalan yang dibincangkan.', 5),
(113, 603, 'e6_n3_s6', 'Jangan campur aduk, nanti markah dipotong. Tetapi mengapa kita perlu menganalisis warisan perayaan dengan SWOT?', 6),
(104, 603, 'e6_n3_s7', 'Boleh ringkaskan perbezaan dahulu dan kini sebelum kedai ditutup?', 1),
(113, 603, 'e6_n3_s7', 'Dan apa yang masih kekal?', 2),
(103, 603, 'e6_n3_s7', 'Balik ke kampung ialah tradisi menjelang perayaan yang kekal. Duit raya dan angpau pula pemberian yang kekal sehingga kini.', 3),
(103, 603, 'e6_n3_s7', 'Kunjung-mengunjung ialah amalan budaya yang kekal dalam masyarakat. Rumah terbuka pula rumah yang dapat dikunjungi semua orang pada hari perayaan.', 4),
(NULL, 603, 'e6_n3_s7', 'Aku akan padankan setiap amalan dengan penerangannya.', 5),
(104, 603, 'e6_n3_s7', 'Jangan lupa rumah terbuka. Nah, kalau semua amalan ini dihormati, apa yang akan berlaku kepada negara kita?', 6);
INSERT INTO QuestionBank (bankID, eraID) VALUES (6, 6)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(601, 6, 'Hari Raya Aidilfitri disambut pada...', '10 Zulhijah', '1 Syawal', '1 Muharam', '12 Rabiulawal', 'B', 'Selepas puasa sebulan.', 'Aidilfitri disambut pada 1 Syawal selepas menjalani ibadah puasa selama sebulan.'),
(602, 6, 'Hari Raya Aidiladha disambut pada...', '10 Zulhijah', '1 Syawal', '1 Ramadan', '1 Muharam', 'A', 'Hari Tasyrik 11, 12 dan 13.', 'Aidiladha disambut pada 10 Zulhijah dan diteruskan pada hari Tasyrik.'),
(603, 6, 'Umat Islam mengadakan ibadah korban dan memberi sedekah daging pada sambutan...', 'Hari Raya Aidilfitri', 'Hari Wesak', 'Pesta Kaamatan', 'Hari Raya Aidiladha', 'D', 'Perayaan bulan Zulhijah.', 'Ibadah korban dilakukan pada Aidiladha.'),
(604, 6, 'Tahun Baharu Cina disambut pada...', 'hari ke-15 kalendar Cina', '25 Disember', 'hari pertama dalam kalendar Cina', 'bulan Aippasi', 'C', 'Berlanjutan 15 hari.', 'Tahun Baharu Cina disambut pada hari pertama kalendar Cina dan berlanjutan 15 hari hingga Chap Goh Meh.'),
(605, 6, 'Tahun Baharu Cina berlanjutan 15 hari hingga hari...', 'Thaipusam', 'Chap Goh Meh', 'Wesak', 'Tasyrik', 'B', 'Hari terakhir sambutan.', 'Perayaan berlanjutan selama 15 hari hingga Chap Goh Meh.'),
(606, 6, 'Perayaan yang menandakan kecerahan mengatasi kegelapan ialah...', 'Deepavali', 'Thaipusam', 'Vaisakhi', 'Wesak', 'A', 'Menghias rumah dengan kolam dan pelita.', 'Deepavali menandakan kecerahan mengatasi kegelapan atau kebijaksanaan mengatasi kejahilan.'),
(607, 6, 'Deepavali disambut pada bulan...', 'Vaisakh', 'Syawal', 'Zulhijah', 'Aippasi', 'D', 'Mengikut kalendar masyarakat Hindu.', 'Deepavali disambut pada bulan Aippasi.'),
(608, 6, 'Pembayar niat membawa persembahan kepada Dewa Murugan semasa...', 'Deepavali', 'Vaisakhi', 'Thaipusam', 'Krismas', 'C', 'Bulan ke-10 kalendar Hindu.', 'Pembayar niat membawa persembahan kepada Dewa Murugan semasa Thaipusam.'),
(609, 6, 'Hari Gawai disambut oleh kaum Dayak, Iban dan Bidayuh pada...', '1 Mei', '1 Jun', '25 Disember', '31 Disember', 'B', 'Setiap tahun.', 'Hari Gawai disambut pada 1 Jun setiap tahun.'),
(610, 6, 'Tarian yang dipersembahkan di rumah panjang semasa Hari Gawai ialah...', 'ngajat', 'sumazau', 'sewang', 'bhangra', 'A', 'Tarian kaum Iban.', 'Persembahan ngajat diadakan di dalam rumah panjang semasa Hari Gawai.'),
(611, 6, 'Pesta Kaamatan disambut oleh kaum...', 'Iban dan Bidayuh', 'Cina dan India', 'Jakun dan Semai', 'Kadazandusun dan Murut', 'D', 'Pada bulan Mei.', 'Pesta Kaamatan disambut oleh kaum Kadazandusun dan Murut pada bulan Mei.'),
(612, 6, 'Upacara ritual semasa Pesta Kaamatan dikendalikan oleh...', 'Lemambang', 'Tok Batin', 'Bobohizan', 'Penghulu', 'C', 'Upacara Magavau.', 'Upacara Magavau dikendalikan oleh Bobohizan.'),
(613, 6, 'Pemenang Unduk Ngadau dahulu dipilih berdasarkan semangat...', 'Kinorohingan', 'Huminodun', 'Petara', 'Waheguru', 'B', 'Kesanggupan berkorban.', 'Dahulu pemenang dipilih berdasarkan semangat Huminodun.'),
(614, 6, 'Bagaimanakah pemenang Unduk Ngadau dipilih pada masa kini?', 'Sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau', 'Upacara ritual antara peserta', 'Berdasarkan semangat Huminodun', 'Sesi soal jawab tentang kecantikan peserta', 'A', 'Berbeza daripada dahulu.', 'Kini pemenang dipilih melalui soal jawab tentang sejarah dan kehidupan masyarakat lampau.'),
(615, 6, 'Krismas disambut pada...', '1 Jun', '1 Syawal', '31 Disember', '25 Disember', 'D', 'Setiap tahun.', 'Krismas disambut penganut Kristian pada 25 Disember.'),
(616, 6, 'Krismas disambut bersempena dengan...', 'hari kemerdekaan negara', 'hari tuaian padi', 'hari kelahiran Jesus Christ', 'hari kelahiran Siddharta', 'C', 'Diiringi nyanyian karol.', 'Krismas memperingati hari kelahiran Jesus Christ.'),
(617, 6, 'Hari Wesak dikaitkan dengan peristiwa penting dalam hidup...', 'Guru Nanak', 'Siddharta Gautama', 'Jesus Christ', 'Lao Tzu', 'B', 'Tiga peristiwa penting.', 'Wesak dikaitkan dengan kelahiran, kesempurnaan fikiran dan nirwana Siddharta Gautama.'),
(618, 6, 'Penganut Buddha memandikan patung Buddha Siddharta semasa Wesak bermaksud...', 'penyucian diri', 'meraikan tahun baharu', 'mensyukuri hasil tuaian', 'menghalau roh jahat', 'A', 'Mengagih makanan kepada sami.', 'Memandikan patung Buddha bermaksud penyucian diri.'),
(619, 6, 'Vaisakhi disambut oleh kaum...', 'Siam', 'Serani', 'Chetti', 'Sikh', 'D', 'Sembahyang di Gurdwara.', 'Vaisakhi disambut oleh kaum Sikh pada bulan keempat Vaisakh.'),
(620, 6, 'Tarian yang diadakan di luar Gurdwara semasa Vaisakhi ialah...', 'Ngajat dan sumazau', 'Zapin dan makyung', 'Bhangra dan Gidha', 'Branyo dan frapeirra', 'C', 'Tarian masyarakat Sikh.', 'Semasa Vaisakhi, tarian Bhangra dan Gidha diadakan.'),
(621, 6, 'Suku Jakun menyebut sambutan tahun baharu Orang Asli sebagai...', 'Jis Pai', 'Tahon Baro', 'Tahun Bahauk', 'Tawun Empai', 'B', 'Bermula 31 Disember.', 'Suku Jakun menyebutnya Tahon Baro.'),
(622, 6, 'Suku Semai menyebut sambutan tahun baharu Orang Asli sebagai...', 'Jis Pai', 'Tahon Baro', 'Tahun Bahauk', 'Tawun Empai', 'A', 'Suku Semai juga meraikan Hari Genggulang.', 'Suku Semai menyebutnya Jis Pai.'),
(623, 6, 'Orang Asli di Selangor dan Negeri Sembilan meraikan...', 'Hari Genggulang', 'San Pedro', 'Tahun Bahauk', 'Hari Moyang', 'D', 'Menghormati nenek moyang.', 'Orang Asli di Selangor dan Negeri Sembilan meraikan Hari Moyang.'),
(624, 6, 'San Pedro disambut oleh masyarakat berketurunan...', 'Cina di Pulau Pinang', 'India di Perak', 'Portugis di Melaka', 'Siam di Kedah', 'C', 'Pada bulan Jun.', 'San Pedro disambut oleh masyarakat berketurunan Portugis di Melaka.'),
(625, 6, 'San Pedro meraikan...', 'hasil sawah', 'penaung nelayan', 'tahun baharu', 'tokoh agama Buddha', 'B', 'Kapal-kapal dihias indah.', 'San Pedro meraikan penaung nelayan; tarian branyo ditarikan.'),
(626, 6, 'Antara berikut, tujuan perayaan untuk mensyukuri hasil tanaman atau hasil laut ialah...', 'Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro', 'Aidilfitri, Aidiladha dan Krismas', 'Tahon Baro dan Jis Pai', 'Deepavali dan Wesak', 'A', 'Fikirkan tuaian dan laut.', 'Gawai, Kaamatan, Vaisakhi dan San Pedro disambut untuk mensyukuri hasil tanaman atau hasil laut.'),
(627, 6, 'Perayaan yang bertujuan mengingati tokoh agama ialah...', 'Deepavali', 'Hari Gawai', 'Tahun Baharu Cina', 'Hari Wesak', 'D', 'Siddharta Gautama.', 'Wesak bertujuan mengingati tokoh agama.'),
(628, 6, 'Perayaan yang bertujuan mengharapkan unsur baik mengatasi kejahatan ialah...', 'Hari Wesak', 'Krismas', 'Deepavali', 'San Pedro', 'C', 'Kecerahan atas kegelapan.', 'Deepavali: unsur baik mengatasi kejahatan.'),
(629, 6, 'Dahulu kad ucapan raya dihantar melalui...', 'media sosial', 'pos atau serahan tangan', 'telefon pintar', 'aplikasi mesej', 'B', 'Sebelum internet.', 'Dahulu kad ucapan dihantar melalui pos atau diserahkan secara peribadi.'),
(630, 6, 'Kini ucapan perayaan dihantar menggunakan...', 'media elektronik dan media sosial', 'pos sahaja', 'merpati pos', 'surat khabar sahaja', 'A', 'Mudah dan pantas.', 'Kini ucapan dihantar melalui media elektronik dan media sosial.'),
(631, 6, 'Dahulu kolam Deepavali dibuat daripada...', 'beras berwarna', 'hampas kelapa berwarna', 'pasir', 'tepung', 'D', 'Berbeza dengan kini.', 'Dahulu kolam dibuat daripada tepung; kini daripada beras atau hampas kelapa berwarna-warni.'),
(632, 6, 'Manakah amalan yang terus kekal dalam sambutan perayaan?', 'Penghantaran kad melalui pos sahaja', 'Membuat kolam daripada tepung sahaja', 'Pemberian duit raya dan amalan kunjung-mengunjung', 'Makan besar di rumah sahaja', 'C', 'Tidak berubah dari dahulu.', 'Duit raya, angpau, balik kampung dan kunjung-mengunjung kekal sehingga kini.'),
(633, 6, 'Berapakah perayaan utama yang dikenali sebagai Rumah Terbuka Malaysia?', 'Empat', 'Enam', 'Lapan', 'Dua belas', 'B', 'Termasuk Aidilfitri dan Krismas.', 'Kerajaan menetapkan enam perayaan utama sebagai Rumah Terbuka Malaysia.'),
(634, 6, 'Apakah kelebihan peralatan moden dalam penyediaan kuih pada masa kini?', 'Memudahkan dan mempercepat penyediaan kuih', 'Menyukarkan penyediaan kuih', 'Menghilangkan gotong-royong sepenuhnya', 'Menambah kos tanpa faedah', 'A', 'Fikirkan kemudahan.', 'Peralatan moden memudahkan dan mempercepat penyediaan kuih; kuih raya juga mudah dibeli.'),
(635, 6, 'Apakah kepentingan menghormati kepelbagaian sambutan dan adab perayaan?', 'Menambah salah faham', 'Menjauhkan satu kaum daripada yang lain', 'Menghentikan perayaan kaum lain', 'Mengekalkan keamanan dan keharmonian negara', 'D', 'Fikirkan perpaduan.', 'Menghormati kepelbagaian sambutan mengekalkan keamanan dan keharmonian negara dan memupuk bertolak-ansur.'),
(636, 6, 'Datuk anda berasa sedih kerana keluarga memilih makan besar Tahun Baharu Cina di restoran. Bagaimanakah anda menenangkannya?', 'Tradisi sudah hilang sepenuhnya kerana tidak lagi dilakukan di rumah sendiri', 'Tradisi itu dianggap salah kerana tidak lagi mengikut cara lama sepenuhnya', 'Tradisi masih diraikan kerana keluarga tetap berkumpul bersama-sama', 'Tradisi itu tidak perlu diraikan lagi pada zaman sekarang', 'C', 'Fikirkan perkara yang tidak berubah.', 'Tempat boleh berubah, tetapi tradisi berkumpul bersama keluarga pada malam Tahun Baharu Cina masih diraikan.'),
(637, 6, 'Kad ucapan raya dahulu dihantar melalui pos, tetapi kini melalui media sosial. Apakah kelebihan cara kini?', 'Ucapan tidak lagi perlu ditulis dengan ikhlas kerana semuanya sudah automatik', 'Ucapan sampai kepada penerima dengan lebih cepat dan mudah', 'Ucapan hanya boleh dihantar kepada orang yang tinggal jauh', 'Ucapan tidak boleh dibaca oleh sesiapa selain penerima sahaja', 'B', 'Bandingkan dengan menunggu berhari-hari.', 'Ucapan melalui media elektronik dan media sosial sampai dalam sekelip mata berbanding kad yang dihantar melalui pos.'),
(638, 6, 'Kuih raya kini mudah dibeli di kedai. Apakah semangat dahulu yang masih boleh dipelihara oleh keluarga anda?', 'Berkongsi kuih dengan jiran dan saudara semasa kunjung-mengunjung', 'Meninggalkan amalan melawat jiran kerana kuih sudah dijual', 'Menyimpan semua kuih untuk diri sendiri sepanjang musim perayaan itu', 'Menggantikan semua perayaan dengan membeli kuih di kedai sahaja', 'A', 'Ingat gotong-royong dan kunjung-mengunjung.', 'Walaupun kuih dibeli, semangat berkongsi dan kunjung-mengunjung masih dapat dikekalkan.'),
(639, 6, 'Rakan berkata Hari Gawai hanya diraikan oleh petani kaum Dayak. Bagaimanakah anda membetulkan kenyataannya?', 'Hari Gawai hanya boleh disambut oleh kaum yang tinggal di rumah panjang di desa', 'Hari Gawai tidak pernah diraikan oleh para petani pada masa lampau sama sekali', 'Hari Gawai sudah berhenti diraikan sejak zaman dahulu lagi', 'Dahulu begitu, tetapi kini diraikan pelbagai kaum tanpa mengira pekerjaan', 'D', 'Bandingkan Gawai dahulu dengan kini.', 'Hari Gawai dahulu diraikan petani Dayak dengan upacara ritual, tetapi kini diraikan oleh pelbagai kaum tanpa mengira bidang pekerjaan.'),
(640, 6, 'Suku Jakun menyebut Tahon Baro, suku Semai menyebut Jis Pai, dan suku Mah Meri menyebut Tawun Empai. Apakah kesimpulan yang paling sesuai?', 'Semua nama itu salah dan perlu digantikan dengan satu nama yang sama sahaja', 'Hanya satu suku yang betul sedangkan semua suku lain telah tersilap menyebutnya', 'Setiap suku mempunyai nama dan budaya sendiri yang patut dihormati', 'Perayaan itu tidak penting kerana nama yang berbeza-beza', 'C', 'Fikirkan hormat kepada kepelbagaian.', 'Nama sambutan tahun baharu yang berbeza menunjukkan setiap suku mempunyai budaya sendiri yang patut dihormati.'),
(641, 6, 'Apakah kesan baik Rumah Terbuka Malaysia kepada masyarakat berbilang kaum?', 'Setiap kaum hanya mengunjungi rumah kaum sendiri sahaja sepanjang perayaan', 'Semua kaum saling berkunjung dan perpaduan bertambah erat', 'Perayaan hanya dinikmati oleh keluarga yang kaya dan berpengaruh sahaja', 'Kunjung-mengunjung dihentikan supaya tidak mengganggu jiran', 'B', 'Ingat rumah yang dapat dikunjungi semua orang.', 'Rumah terbuka membolehkan semua orang berkunjung pada hari perayaan lalu mengeratkan perpaduan.'),
(642, 6, 'Pemenang Unduk Ngadau kini dipilih melalui sesi soal jawab tentang sejarah dan kehidupan lampau. Apakah kebaikan perubahan ini?', 'Peserta digalakkan mengenali sejarah dan warisan masyarakatnya', 'Peserta tidak perlu mengetahui apa-apa pun tentang pesta tersebut dan sejarahnya', 'Peserta hanya dinilai berdasarkan keupayaan menari di atas pentas sahaja', 'Peserta dipilih tanpa mengambil kira pengetahuan sama sekali', 'A', 'Fikirkan sejarah dan warisan.', 'Sesi soal jawab menggalakkan peserta mempelajari sejarah dan kehidupan masyarakat lampau, sambil semangat Huminodun tetap dikenang.'),
(643, 6, 'Dalam analisis SWOT warisan perayaan, belia kurang berminat dengan tradisi lama. Ke dalam bahagian manakah perkara ini diletakkan?', 'Kekuatan yang membantu mengekalkan warisan perayaan', 'Peluang untuk mengekalkan warisan perayaan', 'Perayaan yang tidak perlu dikekalkan lagi pada zaman sekarang ini', 'Halangan dan cabaran mengekalkan warisan perayaan', 'D', 'Fikirkan perkara yang menyukarkan.', 'Minat belia yang kurang ialah cabaran yang menyukarkan usaha mengekalkan warisan perayaan.'),
(644, 6, 'Anda dijemput ke rumah jiran yang menyambut perayaan berlainan kaum. Apakah tindakan yang paling bertolak-ansur?', 'Meniru sahaja adab perayaan sendiri tanpa bertanya kepada tuan rumah itu', 'Menolak jemputan itu kerana adabnya berbeza daripada adab kita sendiri', 'Bertanya tentang adab perayaan dahulu dan menghormati caranya', 'Mengkritik cara sambutan jiran di hadapan tetamu lain', 'C', 'Ingat menghormati kepelbagaian sambutan dan adab.', 'Bertanya tentang adab dan menghormati cara sambutan memupuk bertolak-ansur serta mengekalkan keharmonian.');
